const ozArt7Kolay = <(String, String, List<String>, String)>[
  ('Gros\'un Napoléon dönemi savaş tablolarında, kahramanın yanında ölü ve yaralıların acısını da büyük bir dramla göstermesi sonraki kuşağa ne kazandırmıştır?', 'Romantik ressamlara örnek olan duygu yüklü bir anlatım', ['Neoklasik kurallara sıkı bağlılığın bir örneği', 'Manzarayı tarih resminden üstün tutan bir anlayış', 'Rengi tamamen dışlayan katı ve soğuk bir desen disiplini'], 'Gros, David\'in öğrencisi olsa da coşkulu renk ve acı dolu sahneleriyle Géricault ve Delacroix\'ya yol açan bir öncü sayılır.'),
  ('Géricault, \'Medusa\'nın Salı\' için hazırlanırken hastane morglarından kesik uzuvlar getirip incelemiş ve hayatta kalanlarla görüşmüştür. Bu hazırlık onun hangi tutumunu gösterir?', 'Çağdaş bir felaketi belgeye dayalı gerçeklikle anlatma isteğini', ['Konuyu tamamen hayal gücüyle kurma isteğini', 'Antik heykelleri doğrudan kopyalama alışkanlığını', 'Tabloyu küçük boyutlu ve hızlı bir eskiz olarak bırakma niyetini'], 'Géricault salın maketini bile yaptırmıştı; araştırmaya dayalı bu yöntem romantizmle realizm arasında bir köprü kurar.'),
  ('Delacroix\'nın 1822\'de Salon\'a ilk kez kabul edilen, Dante ile Vergilius\'u yeraltı dünyasında bir kayıkta gösteren tablosunun konusu hangi edebi eserden alınmıştır?', 'İlahi Komedya', ['Aeneis', 'Kurtarılmış Kudüs', 'Çılgın Orlando'], '\'Dante\'nin Kayığı\' İlahi Komedya\'nın Cehennem bölümünden bir sahneyi işler; Delacroix\'nın sanat dünyasına girişini sağlamıştır.'),
  ('Delacroix, gölgeleri siyahla koyulaştırmak yerine tamamlayıcı renklerle kurmayı denemiştir. Bu yaklaşım hangi sonraki ressamlar tarafından özellikle benimsenmiştir?', 'İzlenimciler ve Yeni İzlenimciler', ['Nazarenler ile Prerafaelit Kardeşlik üyeleri', 'Akademik tarih ressamları', 'Biedermeier ressamları'], 'Signac\'ın kitabı da Delacroix\'yı Yeni İzlenimciliğin öncüsü sayar; renkli gölge fikri izlenimci paletin temelidir.'),
  ('Delacroix\'nın Lord Byron\'ın şiirlerinden konu seçmesi romantik ressamların hangi eğilimini yansıtır?', 'Çağdaş edebiyattan beslenip tutkulu kahramanları resmetmeyi', ['Yalnız İncil konularını tarih resmine uygun bulup edebiyatı dışlamayı', 'Gündelik köylü yaşamını belgelemeyi', 'Edebiyattan bağımsız saf soyutlamayı'], 'Byron, Shakespeare, Dante ve Goethe romantik ressamların başlıca kaynaklarıydı; tutku, egzotizm ve trajik kahraman romantizmin sevdiği temalardır.'),
  ('Romantik bir ressamın, çağdaş bir savaşta sivillerin yaşadığı acıyı kalıplaşmış kahramanlık yerine çaresiz figürlerle göstermesi, Neoklasik tarih resminden hangi yönüyle ayrılır?', 'Erdem dersi vermek yerine acıyı ve duyguyu öne çıkarması', ['Antik kahramanları örnek alması', 'Net konturları, düzgün yüzeyi ve antik kahramanları yeğlemesi', 'Konuyu Roma tarihinden seçmesi'], 'Neoklasik tarih resmi ahlaki örnek sunarken romantik resim izleyicide acıma ve dehşet uyandırmayı amaçlar; \'Sakız Katliamı\' buna örnektir.'),
  ('Goya\'nın \'Savaşın Felaketleri\' dizisi Goya\'nın sağlığında yayımlanmamış, ancak 1863\'te basılmıştır. Bu gecikmenin en olası nedeni nedir?', 'İçeriğinin siyasi açıdan tehlikeli bulunması', ['Bakır kalıpların savaş sırasında kaybolup geç bulunması', 'Goya\'nın baskıları eksik bırakması', 'Baskı tekniğinin henüz bilinmemesi'], 'Dizi hem Fransız askerlerinin hem İspanyolların vahşetini gösterdiğinden geri dönen mutlakiyetçi rejimde yayımlanması riskliydi.'),
  ('Turner\'ın 1840 tarihli \'Köle Gemisi\' tablosunda ön planda dalgalar arasında zincirli bacaklar görülür. Tablo hangi tarihsel uygulamayı eleştirir?', 'Hasta köleleri sigorta için denize atma uygulamasını', ['Gemilerde zorunlu askerlik uygulamasını', 'Balina avcılığının yaygınlaşmasını', 'Göçmen gemilerinin yasal sınırın üstünde aşırı doldurulmasını'], 'Tablo, hastalanan kölelerin sigorta parası alınabilsin diye denize atıldığı Zong gemisi olayını hatırlatır ve kölelik karşıtı bir mesaj taşır.'),
  ('Constable\'ın \'Saman Arabası\' tablosunun 1824 Paris Salonu\'nda altın madalya kazanmasının Fransız resmine etkisi en iyi nasıl tanımlanır?', 'Doğrudan gözleme dayalı taze manzara anlayışını Fransız ressamlara tanıtması', ['Fransız ressamları yeniden antik konulu tarih resmine geri döndürmesi', 'Fransa\'da manzara resmini yasaklatması', 'Neoklasik desen anlayışını güçlendirmesi'], 'Delacroix\'nın tabloyu görünce \'Sakız Katliamı\'nın arka planını yeniden düzenlediği anlatılır; tablo Barbizon ressamlarını da etkilemiştir.'),
  ('Constable\'ın \'Resim bir bilimdir; doğanın yasalarının araştırılması olarak sürdürülmelidir\' sözü onun manzaraya yaklaşımını nasıl özetler?', 'Manzarayı dikkatli gözlemle doğayı anlama yolu olarak görmesini', ['Manzarayı yalnız hayal gücüyle ve atölyede kurmayı yeğlemesini', 'Bilimsel aletleri tablolarına konu almasını', 'Ressamların matematik eğitimi almasını şart koşmasını'], 'Constable bu sözü 1836\'daki derslerinde söylemiştir; bulut ve ışık etütleri bu bilimsel gözlem anlayışının ürünüdür.'),
  ('Edmund Burke\'ün 1757\'de yayımlanan incelemesine göre \'yüce\' (sublime) duygusunu en çok hangi deneyim uyandırır?', 'Güvenli bir uzaklıktan izlenen korkutucu büyüklük ve güç', ['Küçük, düzgün ve uyumlu biçimlerin verdiği hoşluk', 'Tanıdık ve gündelik nesnelerin rahatlığı', 'Simetrik bahçelerin sakin düzeni'], 'Burke, güzelliği küçüklük ve düzgünlükle; yüceyi ise uçurum, fırtına ve sonsuzluk gibi korku katılmış bir hayranlıkla ilişkilendirmiştir.'),
  ('Romantik ressamların yıkık manastırları, kale kalıntılarını ve mezarlıkları sıkça resmetmesi en çok hangi duyguyla ilişkilendirilir?', 'Zamanın geçiciliği ve yitip giden geçmişe duyulan özlem', ['Sanayi devriminin ilerlemesine ve makinelere duyulan güven', 'Antik Roma\'nın erdemlerine dönüş isteği', 'Kent yaşamının canlılığına duyulan coşku'], 'Harabe, romantizmde insan eserlerinin doğa ve zaman karşısında yenilgisini ve melankoliyi simgeler.'),
  ('Friedrich\'in \'Denizdeki Keşiş\' tablosunda koca bir gökyüzü ve karanlık denizin önünde küçücük tek bir figür vardır. Bu kompozisyonun yarattığı en belirgin etki hangisidir?', 'Sonsuzluk karşısında insanın yalnızlığı ve küçüklüğü', ['Kalabalık bir liman kentinin canlılığı', 'Antik bir mitin kahramanca anlatımı', 'Gündelik balıkçılık işinin ayrıntılı ve belgesel biçimde anlatımı'], 'Ön planı neredeyse boş bırakan radikal kompozisyon, izleyiciyi sınırsız bir boşlukla yüz yüze bırakır; Kleist tablo için \'göz kapakları kesilmiş gibi\' demiştir.'),
  ('Caspar David Friedrich\'in yaşamının büyük bölümünü geçirdiği ve çevresindeki doğayı resimlerine konu ettiği Alman kenti hangisidir?', 'Dresden', ['Münih', 'Düsseldorf', 'Weimar'], 'Friedrich Greifswald\'da doğmuş, 1798\'den sonra Dresden\'e yerleşmiştir; Elbe kumtaşı dağları gibi yakın bölgeler resimlerinde sık görülür.'),
  ('Fransa\'nın ABD\'ye armağanı olarak 1886\'da New York limanında açılan dev \'Dünyayı Aydınlatan Özgürlük\' heykelinin heykeltıraşı kimdir?', 'Frédéric Auguste Bartholdi', ['Auguste Rodin', 'Jean-Baptiste Carpeaux', 'Aristide Maillol'], 'Bartholdi heykelin dış biçimini tasarlamış; bakır kaplamayı taşıyan iç demir iskeleti Gustave Eiffel\'in ekibi hesaplamıştır.'),
  ('Fransız akademik geleneğindeki tür hiyerarşisinde en yüksek saygınlık hangi türe verilirdi?', 'Tarih resmi', ['Portre', 'Manzara', 'Tür (janr) resmi'], 'Dinsel, mitolojik ve tarihsel anlatıları içeren tarih resmi, hayal gücü ve bilgi gerektirdiği için en üst türe yerleştirilmiştir.'),
  ('William-Adolphe Bouguereau\'nun resimlerinde fırça izinin hiç görülmediği, mine gibi pürüzsüz yüzey anlayışı, izlenimcilerin yaklaşımıyla karşılaştırıldığında hangi farkı gösterir?', 'Bitmişlik ve kusursuzluğu, izlenimcilerse fırça izini ve anlıklığı öne çıkarır', ['İkisi de fırça izini gizleyip pürüzsüz bir yüzey elde etmeyi en önemli ölçüt sayar', 'Bouguereau açık havada, izlenimciler atölyede çalışmıştır', 'İkisi de yalnız sanayi kentlerini konu almıştır'], 'Akademik ressamlar \'fini\' denen pürüzsüz bitişi ustalık ölçütü sayarken izlenimciler görünür fırça vuruşlarını bilerek bırakmıştır.'),
  ('Salon\'da tablolar yan yana ve üst üste neredeyse tavana kadar asılırdı. Bu düzen genç ve tanınmamış bir sanatçı için hangi sorunu doğururdu?', 'Eserinin tavana yakın asılıp görünmez kalması', ['Eserini jüri yerine kendisinin seçip asmak zorunda kalması', 'Eserinin ücretsiz olarak satılması', 'Eserinin müzeye zorla bağışlanması'], 'Jüri ve asıcılar ünlü sanatçıların eserlerini göz hizasına, tanınmamışlarınkini ise çok yükseğe asabiliyordu; bu da eserin fark edilmesini zorlaştırırdı.'),
  ('Courbet\'nin bazı eserleri 1855 Paris Dünya Sergisi\'ne kabul edilmeyince ressamın verdiği tepki hangisidir?', 'Sergi alanının yakınında kendi pavyonunu kurmak', ['Eserlerini halka açık bir meydanda yakarak protesto etmek', 'Fransa\'yı terk edip Londra\'ya yerleşmek', 'Sergi jürisine dava açıp kazanmak'], 'Courbet kendi parasıyla \'Realizm Pavyonu\'nu kurmuş ve kataloğa yazdığı önsözle Realizmin manifestosunu ortaya koymuştur.'),
  ('Courbet\'nin, yolda karşılaştığı hamisi Alfred Bruyas ile hizmetçisinin onu selamladığını gösteren ve \'Bonjour Monsieur Courbet\' adıyla da bilinen tablosu sanatçının hangi öz imgesini yansıtır?', 'Kimseye boyun eğmeyen, özgür ve gururlu gezgin sanatçı', ['Hamisine ve onun zevkine boyun eğen sadık bir saray ressamı', 'Akademi kurallarına uyan uysal öğrenci', 'Kenti hiç terk etmeyen atölye ressamı'], '\'Karşılaşma\'da Courbet başı dik, sırt çantalı bir gezgin olarak durur; hamisi ise onu selamlar. Bu, sanatçının bağımsızlığını vurgulayan bir sahnedir.'),
  ('Courbet\'nin 1870\'te kendisine verilmek istenen Legion d\'honneur nişanını reddetmesi onun hangi tutumuyla tutarlıdır?', 'Resmi kurumların himayesine karşı bağımsız kalma isteğiyle', ['İkinci İmparatorluğa ve III. Napoléon\'a duyduğu derin bağlılıkla', 'Akademiye seçilme isteğiyle', 'Yalnız İngiliz ödüllerini kabul etmesiyle'], 'Courbet, sanatçının devletten onay beklememesi gerektiğini savunmuş, nişanı reddettiğini açık bir mektupla duyurmuştur.'),
  ('Millet\'nin, tarlanın ortasında uzaktaki kilise çanını duyup başlarını eğerek dua eden bir köylü çiftini gösteren tablosunun adı nedir?', 'Akşam Duası', ['Tohum Eken', 'Patates Ekenler ve Sepetleri', 'Koyun Ağılı'], '\'Angelus\' (1857-59) köylü yaşamının dinginliğini ve dindarlığını yalın bir anıtsallıkla gösterir; 19. yüzyılın en çok çoğaltılan imgelerinden biri olmuştur.'),
  ('Barbizon ressamlarının manzara anlayışını Neoklasik \'tarihsel manzara\'dan ayıran temel fark nedir?', 'Mitolojik figür eklemeden yerel doğayı kendi değeriyle resmetmeleri', ['Manzarayı yalnız antik harabelerle süslemeleri', 'Doğayı yalnızca hayal gücüyle düzenlemeleri', 'Manzarayı yalnız kraliyet bahçeleri ve saray parklarıyla sınırlamaları'], 'Neoklasik manzara ideal bir doğayı mitolojik ya da tarihi bir öyküyle birlikte sunarken Barbizon ressamları Fransız ormanını ve köyünü olduğu gibi konu almıştır.'),
  ('Honoré Daumier\'nin \'Le Charivari\' gibi gazeteler için kırk yılı aşkın sürede ürettiği binlerce siyasi ve toplumsal karikatür çoğunlukla hangi teknikle basılmıştır?', 'Taşbaskı (litografi)', ['Bakır gravür', 'Ağaç oyma baskı (ksilografi)', 'Serigrafi'], 'Daumier yaklaşık dört bin taşbaskı yapmıştır; litografi hızlı çizim ve ucuz çoğaltma sağladığından gündelik basın için idealdi.'),
  ('Daumier\'nin \'Çamaşırcı Kadın\' tablosunda, ağır bir bohçayı taşıyıp çocuğuna merdivende yardım eden kadının yüzü neredeyse ayrıntısızdır. Bu tercih ne etki yaratır?', 'Figürü emekçi kadının anıtsal bir simgesine dönüştürür', ['Kadını yüzünden kolayca tanınan bir soylu olarak öne çıkarır', 'Sahneyi mitolojik bir öyküye bağlar', 'Resmin yarım kaldığını açıkça gösterir'], 'Ayrıntısız yüz ve aydınlık arka plana karşı koyu siluet, figüre kişisellikten çok evrensel bir ağırbaşlılık verir.'),
  ('Kramskoy\'un 1872 tarihli \'Çöldeki İsa\' tablosunda İsa\'nın taşlık bir çölde ellerini kenetlemiş, yorgun ve düşünceli oturması neyi vurgular?', 'Ahlaki seçim karşısındaki insani iç çatışmayı', ['Mucizevi ve göz kamaştırıcı bir zaferi', 'Kalabalık bir vaaz sahnesinin coşkusunu ve halkın sevincini', 'Bizans ikonalarının altın yaldızlı ihtişamını'], 'Kramskoy, İsa\'yı ilahi bir figürden çok, zor bir karar öncesinde yalnız kalmış bir insan olarak göstermiştir.'),
  ('İlya Repin\'in kahkahalar içinde toplanmış Kazakların bir hükümdara alaycı bir yanıt mektubu yazdığını gösteren tablosunda mektup kime yazılmaktadır?', 'Osmanlı padişahına', ['Lehistan-Litvanya kralına', 'Rus çarına', 'Kırım hanına'], '\'Zaporijya Kazakları Türk Sultanına Mektup Yazıyor\' 17. yüzyıldan kalma bir efsaneye dayanır; Repin tabloyu 1880-1891 arasında tamamlamıştır.'),
  ('Repin\'in \'Beklemedikleri\' tablosunda bir ailenin oturma odasına yorgun, eski paltolu bir adam girer ve aile üyeleri şaşkınlıkla ona bakar. Bu adam büyük olasılıkla kimdir?', 'Sürgünden dönen bir siyasi tutuklu', ['Kapıya gelen bir dilenci', 'Yeni atanmış bir köy rahibi', 'Evin borcunu almaya gelmiş yaşlı bir tefeci'], 'Tablo, Çarlık döneminde siyasi sürgünden habersizce eve dönen bir devrimciyi ve ailesinin karışık duygularını anlatır.'),
  ('Vasili Vereşçagin\'in \'Savaşın Apotheozu\' tablosunda çölde yığılmış bir kafatası piramidinin üzerinde kargalar dolaşır. Ressamın çerçeveye yazdığı ithaf neyi gösterir?', 'Bütün çağların fatihlerine yönelik bir savaş eleştirisi', ['Rus ordusunun zaferini kutlama isteği', 'Orta Asya\'da yapılan bir arkeolojik kazının sonuçlarını belgeleme amacı', 'Kafataslarının bir müzeye bağışlandığını'], 'Vereşçagin, savaşın parlak yüzü yerine ölümü gösteren tablolarıyla tanınır; 1871 tarihli bu eser savaş karşıtı resmin simgelerinden biridir.'),
  ('Vasili Perov\'un buz tutmuş bir sokakta, kızak üzerindeki dev bir su fıçısını yokuş yukarı çeken üç yoksul çocuğu gösteren tablosu hangi toplumsal sorunu işler?', 'Çocuk emeği ve kent yoksulluğu', ['Askeri seferberlik', 'Kentlerde konut fazlalığı', 'Köylerde eğitim reformu ve okullaşma'], 'Perov\'un \'Troyka\' (1866) tablosu, zanaat çırağı çocukların ağır koşullarda çalıştırılmasını acı bir gerçekçilikle gösterir.'),
  ('Winslow Homer\'ın 1899 tarihli \'Golf Akıntısı\' tablosunda direği kırılmış bir teknede yalnız kalmış bir denizci, çevresinde köpekbalıkları ve uzakta bir hortumla gösterilir. Bu sahnenin baskın teması nedir?', 'Doğanın kayıtsız gücü karşısında insanın savunmasızlığı', ['Denizcilik ticaretinin kazançlı ve parlak yüzü ile limanların zenginliği', 'Bir deniz savaşının kahramanlığı', 'Tatil beldelerindeki eğlence'], 'Homer\'ın geç dönem deniz resimleri, doğanın tehlikeleri karşısında yalnız kalan insanı dramatik ama abartısız bir gerçekçilikle işler.'),
  ('Thomas Cole\'un 1833-1836 arasında yaptığı beş tabloluk \'İmparatorluğun Seyri\' dizisi aynı manzarada hangi süreci anlatır?', 'Bir uygarlığın doğuşunu, doruğunu ve yıkılışını', ['Bir ailenin dört kuşak boyunca aynı çiftlikte geçen yaşamını', 'Amerikan kıtasının keşif yolculuklarını', 'Bir ırmağın kaynağından denize akışını'], 'Dizi, \'Vahşi Durum\'dan \'Tamamlanma\'ya, ardından \'Yıkım\' ve \'Issızlık\'a giden bir döngüyle imparatorlukların geçiciliği üzerine bir uyarıdır.'),
  ('Whistler\'ın tablolarına \'senfoni\', \'noktürn\' ya da \'düzenleme\' gibi müzik terimlerinden adlar vermesi hangi düşünceyi savunur?', 'Resmin değerinin konudan çok renk ve ton uyumundan geldiğini', ['Her tablonun belirli bir besteye eşlik etmek için yapıldığını', 'Ressamların müzik eğitimi almasının zorunlu olduğunu', 'Resmin yalnız konser salonlarında sergilenmesi gerektiğini'], 'Whistler, müzik nasıl öykü anlatmadan sesleri düzenliyorsa resmin de renkleri düzenlemesi gerektiğini savunmuş, estetizmin \'sanat için sanat\' anlayışını benimsemiştir.'),
  ('Holman Hunt\'ın \'Dünyanın Işığı\' tablosunda İsa elinde fenerle sarmaşıkların bürüdüğü bir kapıyı çalar; kapının dış yüzünde tokmak ya da kol yoktur. Bu ayrıntının anlamı nedir?', 'Kapının yalnız içeriden, insanın isteğiyle açılabileceği', ['Evin uzun zamandır terk edilmiş olduğu', 'İsa\'nın kapıyı zorla kırıp içeri girmek üzere olduğu', 'Ressamın tabloyu bitirmeden bıraktığı'], 'Hunt\'ın simgeciliğine göre kapı insan ruhudur; tokmak olmaması, İsa\'yı içeri almanın insanın kendi seçimine bağlı olduğunu anlatır.'),
  ('George Frederic Watts\'ın \'Umut\' tablosunda gözleri bağlı bir kadın bir küre üzerinde oturur ve yalnız tek teli kalmış bir lir çalar. Tablonun başlığı bu imgeyle birlikte nasıl yorumlanır?', 'Her şey yitirilmişken kalan son olanağa tutunma', ['Müziğin bilimden üstün olduğu inancı', 'Dünyanın keşfedilmeyi bekleyen yeni toprakları', 'Kadınların eğitimden dışlanmasına karşı açık bir protesto'], 'Watts, umudu iyimser bir sevinç olarak değil, tek bir telin verdiği zayıf ama süren bir ses olarak simgeler.'),
  ('Le Havre\'da genç Monet\'yi kara kalem karikatürden açık havada resim yapmaya yönlendiren ve Normandiya plajlarındaki kalabalıkları küçük tuvallerde resmeden ressam kimdir?', 'Eugène Boudin', ['Johan Jongkind', 'Charles Daubigny', 'Camille Corot'], 'Monet, Boudin\'in kendisine doğrudan doğadan resim yapmayı öğrettiğini hep minnetle anmıştır; Corot da Boudin\'i \'gökyüzlerinin kralı\' diye övmüştür.'),
  ('Gustave Caillebotte\'un, çıplak gövdeli işçilerin bir salonun tahta zeminini kazıdığı 1875 tablosu Salon jürisince neden reddedilmiştir?', 'Kent emekçilerini konu almasının kaba bulunması', ['Mitolojik figürlerin yanlış çizilmesi', 'Boyutlarının Salon kurallarında izin verilen ölçüyü çok aşması', 'Başka bir ressamın kopyası sayılması'], '\'Parke Rendeleyenler\' akademik çevrelerce \'bayağı\' bulunmuş; Caillebotte bu tabloyu 1876\'daki ikinci izlenimci sergide göstermiştir.'),
  ('Gustave Caillebotte\'un izlenimci gruba katkısı yalnızca ressamlığıyla sınırlı değildir. Hangisi onun gruba sağladığı başlıca desteklerden biridir?', 'Sergileri finanse edip arkadaşlarının eserlerini alması', ['Akademide izlenimciler için ayrı bir kürsü kurması', 'Grubun bütün eleştirilerini kendi çıkardığı günlük gazetede yazıp yayımlaması', 'İzlenimcilere ücretsiz boya üreten bir fabrika açması'], 'Varlıklı bir aileden gelen Caillebotte, Monet\'nin atölye kirasını ödemek dahil grubun birçok giderini üstlenmiş ve eserlerini satın almıştır.'),
  ('Monet\'nin 1877\'de buharla dolu bir tren istasyonunu farklı açılardan gösteren bir dizi tablo yaptığı Paris garı hangisidir?', 'Saint-Lazare Garı', ['Kuzey Garı', 'Doğu Garı', 'Austerlitz (Orléans) Garı'], 'Monet\'nin Saint-Lazare dizisi, modern demiryolu çağını buhar, cam çatı ve ışık oyunlarıyla gösterir; bir kısmı 1877 sergisinde yer almıştır.'),
  ('Monet\'nin 1876 tablosunda eşi Camille kırmızı, işlemeli bir kimono içinde, sarı peruk takıp elinde yelpazeyle dönerken gösterilir. Bu tablo hangi moda akımını yansıtır?', 'Japonizm', ['Oryantalizm', 'Gotik Uyanış', 'Neo-Rokoko'], '\'Japon Kadın\' tablosu, dönemin Paris\'inde Japon nesnelerine ve giysilerine duyulan ilginin, yani Japonizmin, oyunbaz bir yansımasıdır.'),
  ('Monet\'nin 1873 tarihli \'Capucines Bulvarı\' tablosunda yukarıdan görülen kalabalık, küçük koyu fırça dokunuşlarıyla belirtilmiştir. Bu teknik neyi amaçlar?', 'Hareketli kalabalığın bir bakıştaki izlenimini vermeyi', ['Her yayanın yüzünü bir portre gibi ayrıntılı ve tanınır biçimde göstermeyi', 'Sahneyi gece karanlığında göstermeyi', 'Mimariyi tümüyle gizlemeyi'], 'Ayrıntı yerine leke kullanımı, gözün kalabalığı bir anda nasıl algıladığını aktarır; eleştirmenler ise bu lekelerle alay etmiştir.'),
  ('Monet\'nin 1873 tarihli, bir kadınla çocuğun kırmızı çiçeklerle dolu bir yamaçta yürüdüğünü gösteren ve ilk izlenimci sergide yer alan tablosu hangisidir?', 'Gelincikler', ['Nilüferler', 'İris Bahçesi', 'Lale Tarlaları'], '\'Gelincikler\' (Argenteuil yakınında) kırmızı lekelerle çiçek tarlasını, yamaçta iki kez tekrarlanan anne-çocuk figürleriyle yürüyüşün süresini anlatır.'),
  ('Monet\'nin 1891\'de Durand-Ruel\'in galerisinde gösterdiği saman yığınları dizisinin sergiden kısa süre sonra büyük ölçüde satılması ne anlama geliyordu?', 'İzlenimciliğin ticari başarıya ulaştığını', ['Monet\'nin resmi bıraktığını', 'Akademinin diziyi satın aldığını', 'Dizinin yalnızca Fransa\'da ilgi görüp yurt dışında hiç satılmadığını'], 'Dizinin hızla alıcı bulması, onlarca yıl alay edilen Monet\'nin zengin ve ünlü bir sanatçıya dönüştüğünü gösterir.'),
  ('Renoir\'ın yaşamının son yıllarında romatizmal eklem hastalığıyla mücadelesi hakkında hangisi doğrudur?', 'Fırçası eline tutturularak resim yapmayı sürdürmüştür', ['Hastalık nedeniyle resmi bırakıp yalnızca anılarını yazmaya yönelmiştir', 'Bütün eserlerini öğrencilerine yaptırmıştır', 'Yalnızca heykelle uğraşıp resmi tümüyle bırakmıştır'], 'Elleri biçimini yitirse de Renoir fırçayı elinin arasına sıkıştırarak ya da bağlatarak çalışmayı sürdürmüş; Cagnes-sur-Mer\'de yaşamıştır.'),
  ('Renoir\'ın oğullarından biri 20. yüzyılda hangi alanda ünlü olmuştur?', 'Sinema yönetmenliği', ['Opera besteciliği', 'Mimarlık', 'Fotoğraf muhabirliği'], 'Jean Renoir, \'Büyük Yanılsama\' gibi filmleriyle sinema tarihinin önemli yönetmenlerinden biri olmuş, babası hakkında bir kitap da yazmıştır.'),
  ('Renoir\'a atfedilen \'Bir tablo hoş, neşeli ve güzel olmalı; hayatta yeterince can sıkıcı şey var\' sözü onun konu seçimini nasıl açıklar?', 'Mutlu ve keyifli sahneleri bilinçli olarak yeğlemesini', ['Toplumsal adaletsizliği ve yoksulluğu eleştirmeye odaklanmasını', 'Savaş sahnelerine öncelik vermesini', 'Yalnız dinsel konuları ciddi bulmasını'], 'Renoir\'ın dans, piknik, çocuk ve çıplak figürleri, yaşamın hoş yanlarını öne çıkarma tercihini yansıtır.'),
  ('Degas\'nın \'Opera Orkestrası\' tablosunda ön planda müzisyenler ayrıntılı gösterilirken sahnedeki balerinlerin başları çerçevenin üst kenarında kesilmiştir. Bu kesme neyi yansıtır?', 'Fotoğraf ve Japon baskılarından gelen kadraj anlayışını', ['Tuvalin sonradan kesilip küçültülmesini', 'Ressamın balerinlerin yüzlerini çizmekte zorlandığı için bunlardan kaçınmasını', 'Akademik simetri kurallarına bağlılığı'], 'Degas, kompozisyonu sahnenin rastlantısal bir anı gibi kesip izleyiciyi orkestra çukurundaki bir koltuğa yerleştirir.'),
  ('Degas\'nın 1875 tarihli \'Concorde Meydanı\' tablosunda bir adam ve iki kızı resmin kenarına itilmiş, orta kısım ise neredeyse boş bırakılmıştır. Bu düzenleme hangi etkiyi yaratır?', 'Kent yaşamında anlık, rastlantısal bir bakış izlenimini', ['Kraliyet törenlerinin görkemini', 'Klasik piramit kompozisyonun dengesini ve ağırbaşlı düzenini', 'Dinsel bir sahnenin kutsallığını'], 'Figürlerin farklı yönlere yürüyüp kadrajın kenarlarında kesilmesi, fotoğraf karesi gibi anlık bir kent sahnesi duygusu verir.'),
  ('Degas\'nın ileri yaşlarda pastele ve balmumu heykele daha çok yönelmesinin başlıca nedenlerinden biri olarak hangisi gösterilir?', 'Görme yeteneğinin giderek zayıflaması', ['Yağlı boyanın yasaklanması', 'Pastelin Salon\'da zorunlu olması', 'Ailesinin onu heykeltıraş yapmak istemesi'], 'Gözlerindeki ilerleyen sorun nedeniyle Degas, ayrıntılı yağlı boya yerine daha geniş pastel çizgilere ve dokunarak biçimlendirebildiği heykele yönelmiştir.'),
  ('Manet\'nin 1868 tarihli Émile Zola portresinde, masanın üstündeki duvarda \'Olympia\'nın bir kopyası, bir Velázquez gravürü ve bir Japon baskısı asılıdır. Bu ayrıntılar neyi anlatır?', 'Yazarla ressamın ortak beğenilerini ve dostluğunu', ['Zola\'nın sanat satıcılığı yaptığını', 'Odanın aslında bir müze salonu olduğunu ve Zola\'nın orada çalıştığını', 'Manet\'nin Zola\'yı eleştirdiğini'], 'Zola, Manet\'yi ve \'Olympia\'yı basında savunmuştu; portredeki imgeler bu dayanışmanın ve ortak ilgilerin simgesidir.'),
  ('Pissarro\'nun 1890\'ların sonunda Paris\'teki otel odalarının pencerelerinden günün ve mevsimin farklı anlarında resmettiği diziler en çok neyi konu alır?', 'Kalabalık bulvarlar', ['Kır yolları ve elma bahçeleri', 'Deniz kıyısındaki fırtınalar', 'Kilise içleri'], 'Göz rahatsızlığı nedeniyle açık havada çalışmakta zorlanan Pissarro, Montmartre Bulvarı gibi kent manzaralarını yüksek pencerelerden resmetmiştir.'),
  ('19. yüzyılda kadın ressamların izlenimciler arasında bile çoğunlukla ev içi, bahçe ve aile sahnelerini resmetmesinin en önemli nedeni hangisidir?', 'Kamusal mekânlara yalnız girmelerinin toplumsal olarak kısıtlı olması', ['Kadınların yağlı boya kullanmasının yasayla ve akademi kurallarıyla yasaklanmış olması', 'Salon\'un kadınlardan yalnız natürmort kabul etmesi', 'Ev içi sahnelerin daha yüksek fiyata satılması'], 'Burjuva kadınların gece hayatı ve kent mekânlarındaki hareketi sınırlıydı; bu durum Morisot ve Cassatt\'ın konu seçimini büyük ölçüde belirlemiştir.'),
  ('Mary Cassatt\'ın izlenimciliğin Amerika\'da tanınmasına yaptığı en önemli katkılardan biri hangisidir?', 'Amerikalı koleksiyonculara eser almalarını önermesi', ['New York\'ta bir sanat akademisi kurması', 'İzlenimcilerin eserlerini gümrüğe bildirmeden Amerika\'ya kaçak olarak sokması', 'Amerikan Kongresi\'nde sanat yasası çıkarması'], 'Cassatt\'ın yönlendirmesiyle Louisine ve Henry Havemeyer büyük bir izlenimci koleksiyonu oluşturmuş; bu eserlerin bir kısmı Metropolitan Müzesi\'ne geçmiştir.'),
  ('İzlenimcilerin tuvallerini geleneksel koyu kahverengi ya da kırmızımsı astar yerine beyaz ya da çok açık renkli astarla hazırlamasının amacı nedir?', 'Renklerin daha parlak ve aydınlık görünmesini sağlamak', ['Boyanın daha yavaş kurumasını sağlamak', 'Tuvalin daha ucuza mal olmasını ve daha hızlı hazırlanmasını sağlamak', 'Resmin karanlık salonlarda daha iyi görünmesi'], 'Açık zemin, üstündeki saydam ve yarı saydam katmanlardan yansıyan ışığı artırır; böylece açık hava ışığının parlaklığı daha iyi verilir.'),
  ('Birçok izlenimci ressamın paletlerinden siyahı çıkarmaya çalışması hangi gözleme dayanır?', 'Doğada saf siyahın neredeyse hiç görülmemesi', ['Siyah boyanın o dönemde çok pahalı olması ve kolay bulunamaması', 'Salon jürisinin siyahı yasaklaması', 'Siyahın tüplerde hızla kuruması'], 'İzlenimciler en koyu alanların bile çevredeki ışık ve yansımalarla renklendiğini düşünmüş, koyu tonları mavi, mor ve kahverengi karışımlarıyla kurmuştur.'),
  ('19. yüzyılda kimya sanayisinin ürettiği yeni sentetik pigmentler izlenimci resmi nasıl etkilemiştir?', 'Parlak ve doygun renklere kolay erişim sağlamıştır', ['Ressamları yalnız toprak boyalara ve koyu tonlara mahkûm etmiştir', 'Renkleri soldurduğu için yasaklanmıştır', 'Yalnızca akademik ressamlarca kullanılmıştır'], 'Kobalt mavisi, krom sarısı ve viridian gibi pigmentler, izlenimcilerin ışıltılı paletinin temelini oluşturmuştur.'),
  ('Bir izlenimci, turuncu bir kayığın yanına doğrudan mavi lekeler koyuyor ve iki rengin birbirini daha canlı gösterdiğini fark ediyor. Ressamın yararlandığı ilişki hangisidir?', 'Tamamlayıcı renklerin birbirini güçlendirmesi', ['Sıcak renklerin her zaman geri çekilip uzakta görünmesi', 'Benzer renklerin birbirini söndürmesi', 'Renklerin karışınca beyaza dönmesi'], 'Turuncu ve mavi tamamlayıcıdır; yan yana konduklarında karşıtlık en yüksek düzeye çıkar ve iki renk de daha parlak algılanır.'),
  ('Yeni İzlenimcilerin yöntemiyle izlenimcilerin yöntemi karşılaştırıldığında en temel fark hangisidir?', 'Sezgi yerine bilimsel kurala dayanan sistemli bir yöntem izlemeleri', ['Yeni İzlenimcilerin yalnızca siyah-beyaz çalışması', 'İzlenimcilerin her zaman atölyede, Yeni İzlenimcilerin açık havada çalışması', 'Yeni İzlenimcilerin renk kuramını tümüyle reddetmesi'], 'İzlenimciler anlık izlenimi hızlı vuruşlarla yakalarken Seurat ve Signac renkleri kurallara göre önceden hesaplayıp titizlikle yerleştirmiştir.'),
  ('\'Postizlenimcilik\' teriminin bir akım adı olmaktan çok bir şemsiye kavram sayılmasının nedeni nedir?', 'Ortak üslubu değil, farklı yönlere giden sanatçıları birlikte anması', ['Yalnızca bir sanatçıyı tanımlamak için kullanılması', 'Sanatçıların kendi kurdukları ve tüzüğü olan resmi bir topluluğun adı olması', 'Bir manifestoyla ilan edilip kurallarının yazılı olması'], 'Cézanne\'ın yapısal arayışı, van Gogh\'un dışavurumu, Gauguin\'in sembolizmi ve Seurat\'nın bilimselliği tek bir üsluba sığmaz; terim sonradan konmuş bir dönem etiketidir.'),
  ('Bir öğrenci, Cézanne, van Gogh, Gauguin ve Seurat\'yı \'izlenimciliğin ışık ve renk kazanımlarını alıp başka hedeflere yönelen sanatçılar\' olarak tanımlıyor. Bu tanım hangi kavrama uyar?', 'Postizlenimcilik', ['Akademizm', 'Barbizon Okulu', 'Prerafaelit Kardeşlik akımı'], 'Bu dört sanatçı izlenimciliğin parlak paletini benimsemiş, ama yapı, duygu, simge ya da bilimsel düzen gibi yeni amaçlar gütmüştür.'),
  ('Postizlenimci sanatçıların izlenimcilerden en belirgin ayrıldığı nokta hangisidir?', 'Anlık izlenim yerine yapı, duygu ya da simgeyi öne çıkarmaları', ['Açık havada çalışmayı yasaklamaları', 'Parlak renkleri bırakıp yalnızca kahverengi ve toprak tonlarını kullanmaları', 'Salon\'un tarih resmi geleneğine geri dönmeleri'], 'İzlenimcilik görsel algının bir anını yakalamaya çalışırken postizlenimciler bu algıyı düzen, anlatım ya da anlam açısından yeniden kurmuştur.'),
  ('Cézanne\'ın doğduğu, yaşamının büyük bölümünü geçirdiği ve çevresindeki dağı defalarca resmettiği Güney Fransa kenti hangisidir?', 'Aix-en-Provence', ['Marsilya', 'Arles', 'Nice'], 'Cézanne 1839\'da Aix-en-Provence\'ta varlıklı bir bankacının oğlu olarak doğmuş, Paris dönemlerinden sonra hep buraya dönmüştür.'),
  ('Cézanne, Vollard\'ın portresi için onu çok sayıda oturumda kıpırdamadan poz vermeye zorlamış ve sonunda bile \'gömleğin önünden memnunum\' demiştir. Bu anekdot Cézanne\'ın çalışma biçimi hakkında ne söyler?', 'Çok yavaş, titiz ve eseri hiç bitmiş saymayan bir yöntemi', ['Portreleri tek oturuşta, hızlı fırça vuruşlarıyla ve eskiz yapmadan bitirdiğini', 'Modelleri hiç görmeden fotoğraftan çalıştığını', 'Portre siparişlerini yardımcılarına bıraktığını'], 'Cézanne her renk lekesini uzun gözlemden sonra koyar, eserlerini çoğu zaman yarım sayardı; Vollard\'a \'bir elma gibi otur\' dediği anlatılır.'),
  ('Cézanne\'a atfedilen \'Bir elmayla Paris\'i şaşırtmak istiyorum\' sözü hangi tutumu yansıtır?', 'En basit nesneyle resmin temel sorunlarını çözme iddiasını', ['Provence\'tan getirdiği elmaların ticaretiyle zengin olma isteğini', 'Büyük tarih resimleri yapma kararlılığını', 'Paris\'teki akademiye öğretmen olma hedefini'], 'Cézanne natürmortu, biçim, renk ve mekân sorunlarını araştıran bir laboratuvar olarak kullanmıştır; elma bu arayışın simgesi olmuştur.'),
  ('Cézanne\'ın \'İzlenimcilikten müzelerdeki sanat gibi sağlam ve kalıcı bir şey yapmak istedim\' sözü onun izlenimcilikle ilişkisini nasıl tanımlar?', 'İzlenimci rengi koruyup ona kalıcı bir yapı kazandırmayı', ['İzlenimciliği tümüyle reddedip akademinin tarih resmi geleneğine geri dönmeyi', 'Müzelerdeki eserleri kopyalamakla yetinmesini', 'Yalnız heykel yapmaya yönelmesini'], 'Cézanne, izlenimcilerin parlak paletini benimsemiş ama anlık etkiler yerine geometrik düzen ve sağlamlık aramıştır.'),
  ('Cézanne\'ın suluboyalarında kâğıdın beyaz bölümlerini boyamadan bırakması ne işlev görür?', 'Işığı göstermek ve biçimleri birkaç lekeyle önermek', ['Kâğıttan tasarruf etmek', 'Eserin bitmediğini satıcıya bildirmek', 'Sonradan yağlı boyayla kapatılacak yerleri atölye yardımcısına işaretlemek'], 'Boş bırakılan alanlar renk lekeleri arasında ışık gibi titreşir; geç suluboyalar bu yüzden neredeyse soyut bir hafiflik taşır.'),
  ('Cézanne\'ın 1906\'daki ölümüne yol açan olay nedir?', 'Açık havada fırtınaya yakalanıp hastalanması', ['Atölyesinde çıkan bir yangın', 'Bir at arabası kazası', 'Kullandığı boyalardan uzun süreli kurşun zehirlenmesi'], 'Cézanne bir sağanak altında saatlerce kalıp bayılmış, birkaç gün sonra zatürreden ölmüştür; son günüme dek çalışacağım dediği bilinir.'),
  ('Gauguin\'in 1892 tarihli \'Manao Tupapau\' tablosunda yatakta yüzüstü yatan genç bir Tahitili kadın ve arkada siyah giysili bir figür vardır. Tablonun başlığı neyi anlatır?', 'Ölülerin ruhunun izlediği korkusunu', ['Bir doğum günü kutlamasını', 'Tahiti\'deki bir düğün törenini', 'Denizden dönen balıkçıların karşılanma törenini'], 'Gauguin, Tahitililerin karanlıkta dolaşan ölü ruhlarına duyduğu korkuyu, arka plandaki gizemli figürle simgelediğini yazmıştır.'),
  ('Gauguin\'in ağaç baskılarında kalıbı kasıtlı olarak kaba ve pürüzlü oyması hangi beğeniyi yansıtır?', 'İlkel sayılan sanatların doğrudanlığına hayranlığı', ['Akademik gravürün kusursuzluğuna ve inceliğine sadakati', 'Fotoğrafik gerçekçiliğe ulaşma çabasını', 'Baskı maliyetini düşürme kaygısını'], 'Gauguin Avrupa dışı ve halk sanatlarındaki yalınlığı değerli bulmuş; bu tutum 20. yüzyıl başındaki \'ilkelcilik\' eğilimini önceden haber verir.'),
  ('Nabi grubunun adı olan \'nabi\' sözcüğü İbranice ve Arapçada ne anlama gelir?', 'Peygamber', ['Kardeş', 'Gezgin', 'Usta ressam'], 'Grup kendilerini yeni bir sanatın habercileri olarak gördükleri için bu adı benimsemiştir; adı şair Henri Cazalis önermiştir.'),
  ('Nabilerin resimle sınırlı kalmayıp kitap resimleri, tiyatro dekorları, paravanlar ve duvar panoları da üretmesi hangi düşünceyle tutarlıdır?', 'Sanatı gündelik yaşamın her alanına yayma düşüncesi', ['Yalnızca kâr amacıyla, sanatsal kaygı gütmeden iş yapma isteği', 'Resmi küçümseyip bırakma kararı', 'Akademinin onlara zorunlu olarak verdiği görevler'], 'Nabiler resim ile dekoratif sanatlar arasındaki ayrımı yumuşatmış, duvardan kitap sayfasına dek uyumlu bir sanat ortamı kurmak istemiştir.'),
  ('Toulouse-Lautrec\'in \'Moulin Rouge\'da\' tablosunda sağ kenarda yarısı kesilmiş, yüzü yapay ışıkta yeşilimsi görünen bir kadın vardır. Bu yüzün yeşil boyanması hangi etkiyi yaratır?', 'Gece hayatının yapay ve hastalıklı havasını vurgulamak', ['Kadının bir hayalet olduğunu ve öbür dünyadan geldiğini açıkça belirtmek', 'Tablonun bitmediğini göstermek', 'Doğal gün ışığını aynen yansıtmak'], 'Gaz lambalarının sert ışığı altındaki yeşil yüz, eğlencenin ardındaki yorgunluk ve yapaylığı hissettirir; kesik kadraj Degas ve Japon baskılarını anımsatır.'),
  ('Sembolist ressamların Salome, Sfenks ve Medusa gibi figürleri sıkça işlemesi, dönemin hangi kültürel imgesiyle ilişkilendirilir?', '\'Ölümcül kadın\' (femme fatale) imgesi', ['Erdemli ve çalışkan köylü kadın imgesi', 'Kahraman asker imgesi', 'Bilge yaşlı filozof imgesi'], '19. yüzyıl sonu sembolizmi, arzu ile ölümü birleştiren \'femme fatale\' figürüne takıntılı bir ilgi göstermiştir.'),
  ('Sembolist bir ressamın tablosunda yüzü görünmeyen bir figür, karanlık bir kapı ve sessiz bir su kıyısı yer alıyor; ressam izleyicinin kesin bir öykü yerine bir ruh halini sezmesini istiyor. Bu yaklaşım Realizmden hangi noktada ayrılır?', 'Görüneni belgelemek yerine iç dünyayı çağrıştırması', ['Toplumsal sorunları açıkça eleştirmesi', 'Gündelik işçi yaşamını ayrıntılı ve belgesel bir kesinlikle göstermesi', 'Tarihi bir olayı kesin bir tarihle anlatması'], 'Realizm görünür dünyayı nesnel biçimde gösterirken Sembolizm imgeleri bir düşünce ya da duygunun dolaylı göstergeleri olarak kullanır.'),
  ('Munch\'un \'Çığlık\' imgesini yalnız yağlı boya olarak değil başka tekniklerle de birden çok kez üretmesi, imgenin yaygınlaşmasını nasıl etkilemiştir?', 'Pastel ve taşbaskı versiyonları imgeyi geniş kitlelere ulaştırmıştır', ['Bütün versiyonlar yangında yok olduğu için imge uzun süre unutulup tanınmamıştır', 'Yalnız tek kopya kaldığı için hiç tanınmamıştır', 'Munch versiyonları tek bir tabloda birleştirmiştir'], 'Munch 1893-1910 arasında boyalı, pastel ve taşbaskı versiyonlar yapmış; özellikle siyah-beyaz baskı imgenin yaygın dolaşımını sağlamıştır.'),
  ('Munch\'un \'Vampir\' adıyla bilinen tablosunda bir kadının kızıl saçları öne eğilmiş bir erkeğin başına dökülür. Munch\'un konuyla ilgili temel ilgisini en iyi hangisi açıklar?', 'Aşkın hem şefkat hem tüketici bir güç olarak yaşanması', ['Korku edebiyatındaki canavarları ve efsaneleri ayrıntılı biçimde belgelemek', 'Bir tiyatro oyununun afişini hazırlamak', 'Kadın berberlerinin çalışmasını göstermek'], 'Başlığı Munch\'un dostu Przybyszewski koymuştur; sahne sarılma ile emme arasında bilinçli olarak belirsiz bırakılır ve aşkın çelişkili doğasını anlatır.'),
  ('Bir tablo şöyle tanımlanıyor: köylüler toprak yolda yorgun yürüyor, renkler kahverengi ve toprak tonlarında, figürler idealize edilmemiş ve konu ne mitolojik ne de tarihsel. Bu tablo büyük olasılıkla hangi akıma aittir?', 'Realizm', ['Romantizm', 'Sembolizm', 'Neoklasisizm'], 'İdealleştirmeden gösterilen sıradan emekçiler ve gündelik konu, 19. yüzyıl ortası Realizminin belirgin özellikleridir.'),
  ('Aşağıdaki eşleştirmelerden hangisinde ressam ile ait olduğu akım doğru verilmiştir?', 'Théodore Géricault - Romantizm', ['Gustave Courbet - Sembolizm', 'Georges Seurat - Barbizon Okulu', 'Dante Gabriel Rossetti - İzlenimcilik'], 'Géricault Fransız Romantizminin öncüsüdür; Courbet realist, Seurat Yeni İzlenimci, Rossetti ise Prerafaelittir.'),
  ('Bir öğrenci Barbizon ressamları ile izlenimcileri karşılaştırıyor. Hangisi iki grup arasındaki farkı en iyi özetler?', 'Barbizonlular eserlerini atölyede koyu tonlarla bitirirken izlenimciler açık havada parlak renk kullanmıştır', ['Barbizonlular kent yaşamını ve kafeleri, izlenimciler ise yalnızca ormanları ve dağları resmetmiştir', 'Barbizonlular soyut resim yapmış, izlenimciler fotoğraf kullanmıştır', 'İki grup arasında hiçbir konu ya da teknik ortaklığı yoktur'], 'Barbizon ressamları doğayı gözlemlese de büyük eserlerini atölyede, geleneksel tonlarla bitirmiştir; izlenimciler ise ışığı doğrudan, açık bir paletle yakalamaya yönelmiştir.'),
  ('Romantik bir manzara ressamı ile bir izlenimci aynı fırtınalı denizi resmetseydi, izlenimcinin önceliği büyük olasılıkla hangisi olurdu?', 'Belli bir anın ışık ve renk etkisini yakalamak', ['Doğanın insan üzerindeki ezici gücünü dramatize etmek', 'Bir kahramanın trajik öyküsünü anlatmak', 'Sahneye mitolojik figürler yerleştirmek'], 'Romantik ressam fırtınayı yücelik ve duygu aracı olarak kullanırken izlenimci, suyun ve gökyüzünün o andaki görsel izlenimine odaklanır.'),
  ('Aşağıdaki ressamlardan hangisi Postizlenimciler arasında sayılmaz?', 'Alfred Sisley', ['Paul Cézanne', 'Paul Gauguin', 'Vincent van Gogh'], 'Sisley yaşamı boyunca saf izlenimci manzara anlayışına bağlı kalmıştır; diğer üçü Postizlenimciliğin temel adlarıdır.'),
  ('Prerafaelitler ile Fransız izlenimcileri karşılaştırıldığında hangisi doğrudur?', 'İkisi de akademiye karşıydı; Prerafaelitler ayrıntıyı, izlenimciler anlık ışığı öne çıkardı', ['İkisi de yalnızca kent yaşamını konu almıştır', 'İkisi de ayrıntıyı tümüyle reddetmiştir', 'Prerafaelitler noktacı tekniği bulmuş, izlenimciler ise onu kopyalayıp yaygınlaştırmıştır'], 'Her iki grup da akademiye başkaldırmıştır; ancak Prerafaelitler yaprak yaprak titiz ayrıntı ve edebi konuları, izlenimciler ise hızlı vuruşlarla görsel anı seçmiştir.'),
  ('Yeni İzlenimcilik ile Sembolizm aynı yıllarda Paris\'te gelişmiştir. İkisini birbirinden ayıran temel nokta hangisidir?', 'Birinin bilimsel renk kuramına, ötekinin düşsel anlamlara dayanması', ['Birinin yalnızca heykel, ötekinin yalnızca resim dalında eser vermiş olması ve hiç kesişmemesi', 'Birinin İngiltere\'de, ötekinin Rusya\'da doğması', 'Birinin akademinin resmi üslubu olması'], 'Seurat ve Signac optik kurallarla çalışırken sembolistler görünenin ötesindeki düşünceleri imgelerle çağrıştırmayı amaçlamıştır; yine de Fénéon gibi eleştirmenler iki çevreyle de ilişkiliydi.'),
  ('Bir sergide üç tablo var: biri Napoléon\'u kahramanca öven bir Neoklasik eser, biri bir gemi kazasını dramatize eden Romantik eser, biri de bir köy cenazesini gösteren Realist eser. Bu sıralama hangi değişimi en iyi gösterir?', 'Konunun ideal kahramandan duyguya, oradan sıradan yaşama kayması', ['Rengin tümüyle ortadan kalkması', 'Resmin soyutlamaya yönelmesi', 'Dinsel konuların giderek çoğalıp sonunda tarih resminin yerini tümüyle alması'], '19. yüzyıl Fransız resminde ilgi, örnek alınacak kahramanlardan duygusal yoğunluğa, ardından sıradan insanların yaşamına doğru yer değiştirmiştir.'),
  ('Aşağıdaki ifadelerden hangisi Romantizm için doğru değildir?', 'Akıl ve ölçüyü sanatın en yüksek ilkesi saymıştır', ['Doğanın ürkütücü gücüne ilgi duymuştur', 'Egzotik ve uzak konuları sevmiştir', 'Duygu ve hayal gücünü öne çıkarmıştır'], 'Akıl ve ölçüyü öne çıkaran anlayış Neoklasisizmdir; Romantizm ise duygu, hayal gücü ve yüceliğe yönelmiştir.'),
  ('Monet\'nin \'İzlenim, Gün Doğumu\' ile Turner\'ın geç dönem deniz resimleri karşılaştırıldığında ortak nokta hangisidir?', 'Biçimlerin ışık ve atmosfer içinde çözülmesi', ['Keskin konturlu figürlerin öne çıkması', 'Mitolojik bir öykünün ayrıntılarla ve figürlerle anlatılması', 'Fotoğrafik bir ayrıntı kesinliği'], 'İkisinde de su, sis ve ışık nesnelerin sınırlarını eritir; Monet\'nin 1870\'te Londra\'da Turner\'ı görmüş olması bu benzerliği tartışmaya açar.'),
  ('Bir koleksiyoncu 19. yüzyıl sonundan bir tablo alıyor: yüzeyi binlerce küçük, düzenli renk noktasından oluşuyor ve yakından bakınca renkler ayrık, uzaktan bakınca kaynaşmış görünüyor. Bu eser büyük olasılıkla kime ya da hangi çevreye aittir?', 'Seurat ve Signac çevresi', ['Barbizon ressamları', 'Prerafaelit Kardeşlik ressamları', 'Nazarenler'], 'Düzenli noktalar ve optik karışım, Yeni İzlenimcilerin noktacı yöntemini gösterir.'),
  ('Japon baskılarının Batılı ressamlara önerdiği yeniliklerden hangisi, Degas ve Toulouse-Lautrec\'in kompozisyonlarında özellikle görülür?', 'Figürlerin kadrajın kenarında beklenmedik biçimde kesilmesi', ['Merkezî tek kaçış noktalı perspektif', 'Altın oranın kesin hesaplanması', 'Bütün yüzeyin eşit ayrıntıyla doldurulması'], 'Ukiyo-e baskılarındaki kesik figürler ve çapraz kompozisyonlar, Batı resmindeki merkezî ve dengeli düzene alternatif bir model sunmuştur.'),
  ('Paris\'in Haussmann döneminde geniş bulvarlarla yeniden yapılanması izlenimci resmi en çok hangi yönden etkilemiştir?', 'Yeni kent yaşamını başlıca konu haline getirmesiyle', ['Ressamları kent dışına, kırsal bölgelere sürgün ederek manzaraya yöneltmesiyle', 'Resim satışlarını yasaklamasıyla', 'Atölyelerin tümünü kapatmasıyla'], 'Yeni bulvarlar, garlar ve köprüler Monet, Caillebotte ve Pissarro\'nun kent manzaralarına konu olmuş; modern yaşamın sahnesini oluşturmuştur.'),
  ('Demiryollarının 19. yüzyıl ortasında Paris çevresine yayılmasının izlenimci resme dolaylı bir etkisi hangisidir?', 'Seine kıyısındaki banliyölere kolayca gidilebilmesi', ['Ressamların yalnız tren içlerini resmetmek zorunda kalması', 'Boya fiyatlarının aşırı yükselmesi', 'Açık hava resminin yasaklanması'], 'Argenteuil, Bougival ve Chatou gibi banliyöler trenle ulaşılabilir hale gelmiş; kayıkçılık, piknik ve dans izlenimcilerin sık konuları olmuştur.'),
  ('Augustus Egg\'in 1858 tarihli, üç resimden oluşan \'Geçmiş ve Şimdi\' dizisi bir ailenin dağılışını sırasıyla gösterir. Bu tür Viktorya dönemi eserlerin ortak amacı nedir?', 'İzleyiciye ahlaki bir ders veren resimli bir anlatı sunmak', ['Saf renk ve biçim denemesi yapmak', 'Antik heykelleri ve Yunan vazolarını olduğu gibi kopyalamak', 'Manzarayı bilimsel olarak belgelemek'], 'Viktorya dönemi \'problem resmi\' ya da anlatı resmi, aile, ahlak ve toplumsal düzen üzerine okunacak ipuçlarıyla dolu sahneler kurar.'),
  ('Bir ressam fırtınalı bir dağ geçidinde yıldırımlar arasında küçücük kalmış bir yolcuyu resmediyor ve izleyicide hem korku hem hayranlık uyandırmak istiyor. Bu ressam hangi akımın anlayışına yakındır?', 'Romantizm', ['Realizm', 'Yeni İzlenimcilik', 'Akademik Neoklasisizm'], 'Doğanın ezici gücü karşısında insanın küçüklüğü ve \'yüce\' duygusu Romantik resmin tipik temasıdır.'),
  ('Romantik ressamların Orta Çağ şatolarına, şövalyelere ve Gotik kiliselere ilgi duymasının en önemli nedeni hangisidir?', 'Akılcı antik dünyaya karşı gizemli ve ulusal bir geçmiş araması', ['Orta Çağ yapılarının yeni yapılmış olması', 'Akademinin yalnız Orta Çağ konularını kabul etmesi', 'Gotik kiliselerin resim siparişi vermesi'], 'Romantikler Yunan-Roma idealleri yerine kendi ulusal geçmişlerini, efsanelerini ve dinsel duygularını öne çıkarmıştır.'),
  ('Bir öğrenci Romantik resimde rengin desenden daha önemli sayılmasını açıklamak istiyor. Hangisi en uygun gerekçedir?', 'Rengin duyguyu ve hareketi çizgiden daha doğrudan aktarması', ['Rengin daha ucuz bir malzeme olması', 'Desenin akademilerde yasaklanması', 'Renkli boyaların daha hızlı kuruması'], 'Romantikler, özellikle Delacroix, rengi coşku ve tutkunun dili olarak görmüş; net çizgiyi ise akılcı ve soğuk Neoklasik ölçüyle ilişkilendirmiştir.'),
  ('Romantizmin \'egzotizm\' eğilimine en iyi örnek hangisidir?', 'Kuzey Afrika ve Orta Doğu\'dan renkli, uzak ve masalsı sahneler resmetmek', ['Paris\'teki bir fabrikayı ayrıntılı çizmek', 'Antik bir tapınağın ölçülü planını kopyalamak', 'Bir aile yemeğini sade biçimde göstermek'], 'Romantik sanatçılar uzak coğrafyaları gündelik Avrupa yaşamından kaçışın ve hayal gücünün alanı olarak görmüştür.'),
  ('Romantizm döneminde sanatçının toplumdaki yeri nasıl değişmiştir?', 'Sanatçı iç dünyasını dışa vuran bağımsız bir deha sayılmaya başlanmıştır', ['Sanatçı yalnız sarayın emirlerini uygulayan bir zanaatçı olmuştur', 'Sanatçıların imza atması yasaklanmıştır', 'Sanatçılar yalnızca loncalarda çalışabilmiştir'], 'Romantizm, kurallara bağlı usta yerine duygularını özgürce dışa vuran \'deha\' kavramını yüceltmiş; modern sanatçı imgesi bu dönemde biçimlenmiştir.'),
  ('Realist ressamların tarih resmine yönelik eleştirisinin özü hangisidir?', 'Görülmemiş geçmişi ya da hayali sahneleri gerçekmiş gibi göstermesi', ['Tarih resminin çok küçük boyutlu olması', 'Tarih resminin yalnız renkle yapılması', 'Tarih resminin çok ucuza satılması'], 'Courbet\'ye göre resim somut ve var olan şeylerin sanatıdır; ressam kendi çağını ve kendi gördüğünü resmetmelidir.'),
  ('Bir ressam 1850\'lerde bir köy düğününü ya da bir taş ocağındaki işçileri dev boyutlu tuvallerde resmediyor. Salon izleyicisinin buna tepki göstermesinin en olası nedeni nedir?', 'Dev boyutların yalnız kahramanlara ve kutsal konulara ayrılmış olması', ['Tuvallerin fazla küçük olması', 'Konuların Antik Yunan\'dan alınması', 'Figürlerin idealize edilmesi'], 'Akademik düzende büyük tuval saygın tarih resmine aitti; sıradan insanlara bu ölçeği vermek kurulu hiyerarşiye meydan okumak demekti.'),
  ('Realizmin 1848 devrimleri döneminde güç kazanması hangi toplumsal gelişmeyle ilişkilidir?', 'İşçilerin ve köylülerin siyasal ve toplumsal görünürlüğünün artmasıyla', ['Krallıkların güç kazanıp sanat siparişlerini artırmasıyla', 'Kilisenin bütün sanatı denetim altına almasıyla', 'Antik kazıların çoğalmasıyla'], '1848\'de demokratik ve toplumsal talepler yükselmiş; sanatta da sıradan emekçiler ön plana çıkmıştır.'),
  ('Hangisi Realist bir eserde beklenebilecek bir özellik değildir?', 'Mitolojik tanrıların bulutlar üzerinde gösterilmesi', ['Çalışan insanların yıpranmış giysileri', 'Sıradan bir kır cenazesi', 'Kentteki yoksul bir aile'], 'Realizm görünür, çağdaş ve sıradan yaşamı konu alır; bulutlar üzerindeki tanrılar akademik ya da Barok geleneğe aittir.'),
  ('Bir eleştirmen 1850\'de bir tabloya \'çirkinliğin kutsanması\' diyor. Bu eleştiri en büyük olasılıkla hangi tür esere yöneltilmiştir?', 'Sıradan, yıpranmış insanları güzelleştirmeden gösteren Realist bir esere', ['Mitolojik bir çıplağı gösteren akademik bir esere', 'Antik bir kahramanı yücelten Neoklasik bir esere', 'Melekler ve azizlerle dolu bir sunak resmine'], 'Akademik beğeni güzelliği idealleştirmede görüyordu; Realizmin kusurlu, kirli ve sıradan bedenleri gösterme cesareti bu nedenle \'çirkin\' bulunmuştur.'),
  ('Courbet\'nin birçok otoportresinde kendini tutkulu, umutsuz ya da yaralı bir genç olarak göstermesi, onun Realizme geçmeden önceki hangi eğilimini yansıtır?', 'Romantik bir benlik imgesini', ['Neoklasik bir kahramanlık anlayışını', 'Sembolist bir mistisizmi', 'Noktacı bir renk araştırmasını'], '1840\'lardaki \'Umutsuz Adam\' ve \'Yaralı Adam\' gibi otoportreler, genç Courbet\'nin Romantizmle beslenen dramatik kendini sunma biçimini gösterir.'),
  ('Courbet\'nin \'Ressamın Atölyesi\'nde sağ tarafta yer alan okuyan figürün Charles Baudelaire olması tabloya hangi anlamı katar?', 'Sanatçının çevresindeki edebiyat ve düşünce dostlarını göstermesi', ['Tablonun bir kitap kapağı olarak yapılması', 'Baudelaire\'in tabloyu kendisinin boyaması', 'Ressamın şiiri resimden üstün tutması'], 'Courbet sağ tarafa hamileri, eleştirmenleri ve şair dostlarını yerleştirmiş, onları sanatını destekleyen çevre olarak sunmuştur.'),
  ('Millet\'nin \'Çapalı Adam\' tablosunda, taşlı bir tarlada çapasına dayanıp soluklanan bitkin köylü neyi temsil eder?', 'Topraktaki ağır ve bitmeyen emeğin insan üzerindeki yükünü', ['Kır yaşamının neşeli tatil havasını', 'Varlıklı bir çiftlik sahibinin gururunu', 'Antik bir tanrının toprağa inişini'], 'Tablo köylülüğü romantik bir huzur olarak değil, insanı tüketen bir yük olarak gösterdiği için hem övülmüş hem de eleştirilmiştir.'),
  ('Bir izlenimci, aynı köprüyü sabah, öğle ve akşam üç ayrı tuvalde resmediyor ve her birinde renkler tamamen farklı çıkıyor. Bu deney en iyi hangi düşünceyi gösterir?', 'Nesnenin rengi sabit değildir; ışık değiştikçe gördüğümüz renk de değişir', ['Köprünün üç kez yeniden boyandığını', 'Ressamın renk körü olduğunu', 'Akşamları renklerin tümüyle kaybolduğunu'], 'İzlenimciler \'yerel renk\' denen sabit renk fikrini sorgulamış; görünen rengin ışık ve atmosfere bağlı olduğunu göstermiştir.'),
  ('İzlenimci tablolarda ayrıntılar yakından bakınca dağınık lekeler gibi görünürken birkaç adım geri çekilince sahne birden netleşir. Bu durumun nedeni nedir?', 'Gözün yan yana konmuş renk lekelerini uzaktan birleştirmesi', ['Tabloların arkadan aydınlatılması', 'Ressamların görünmez mürekkep kullanması', 'Tuvalin kendiliğinden renk değiştirmesi'], 'İzlenimci yüzeyler izleyicinin gözünü sürece katar; parçalı vuruşlar belirli bir uzaklıktan bütünlüklü bir görüntüye dönüşür.'),
  ('Bir izlenimci kar manzarası yapıyor. Kar için en olası yaklaşımı hangisidir?', 'Gölgeli bölgelerde mavi ve mor, güneşli bölgelerde sarımsı ve pembe tonlar kullanmak', ['Bütün karı tek düze saf beyazla boyamak', 'Karı siyah konturlarla çevreleyip içini boş bırakmak', 'Karı kahverengi bir zemin üzerinde grileştirmek'], 'Monet ve Sisley\'nin kar manzaraları, beyazın gökyüzü ve güneş ışığına göre renk aldığını gösterir.'),
  ('İzlenimcilerin tablolarını genellikle küçük ve orta boyutlu tuvallere yapmalarının pratik nedeni hangisidir?', 'Açık havada taşınıp hızla bitirilebilmeleri', ['Büyük tuvallerin yasak olması', 'Küçük tuvallerin Salon\'da daha çok ödül alması', 'Büyük tuval yapımı için gereken bezin bulunmaması'], 'Değişen ışığı yakalamak için birkaç saat içinde, yerinde çalışmak gerekiyordu; bu da taşınabilir boyutları zorunlu kılıyordu.'),
  ('Bir öğrenci \'İzlenimciler ayrıntıyı önemsemedi\' diyor. Bu yargıyı daha doğru hale getiren düzeltme hangisidir?', 'İzlenimciler nesnelerin ayrıntısından çok ışığın ve havanın anlık etkisini önemsedi', ['İzlenimciler yalnız portre yaptıkları için manzarayı önemsemedi', 'İzlenimciler renk kullanmadı, yalnızca çizgiye önem verdi', 'İzlenimciler fotoğraf makinesiyle çalıştı'], 'Ayrıntının ihmali bir beceriksizlik değil, bilinçli bir öncelikti: görme deneyimini olduğu gibi aktarmak.'),
  ('Bir izlenimci kayık sahnesinde suya yansıyan ağaçları resmederken yansımayı nasıl gösterir?', 'Yatay, kesik ve titrek fırça vuruşlarıyla', ['Ağaçların keskin ve tam bir kopyasıyla', 'Suyu düz siyah bir alan olarak bırakarak', 'Yansımayı hiç göstermeyip suyu beyaz bırakarak'], 'Hareketli su yüzeyi yansımayı parçalar; izlenimciler bunu kısa yatay vuruşlarla ve renk titreşimiyle vermiştir.'),
  ('İzlenimci ressamların Salon jürisiyle sürekli sorun yaşamasının en temel nedeni hangisidir?', 'Eserlerinin akademinin \'bitmiş yüzey\' ve yüce konu ölçütlerine uymaması', ['Eserlerinin çok pahalı olması', 'Salon\'a hiç başvurmamaları', 'Yabancı uyruklu olmaları'], 'Jüri, görünür fırça izlerini ve gündelik konuları özensizlik sayıyordu; izlenimciler de bu yüzden bağımsız sergiler açmıştır.'),
  ('İzlenimcilerin konu seçimine bakıldığında hangisi onların en az ilgilendiği konudur?', 'Antik mitolojiden kahramanlık sahneleri', ['Kafeler ve bulvarlar', 'Kır gezileri ve piknikler', 'Tren garları ve köprüler'], 'İzlenimciler çağdaş yaşamı ve doğayı resmetmiş; akademinin sevdiği mitolojik ve tarihsel konulara pek yönelmemiştir.'),
  ('İzlenimci tablolarda sık görülen \'kayık partileri\', \'dans bahçeleri\' ve \'deniz kenarı tatilleri\' 19. yüzyıl sonundaki hangi toplumsal değişimi yansıtır?', 'Kentli orta sınıfın boş zaman ve eğlence kültürünün yaygınlaşmasını', ['Köylülüğün yeniden güçlenmesini', 'Savaş hazırlıklarının artmasını', 'Dinsel törenlerin yaygınlaşmasını'], 'Sanayileşme ve ulaşım olanakları, orta sınıfın hafta sonu eğlencelerini ve banliyö gezilerini mümkün kılmış; bu yeni yaşam izlenimcilerin başlıca konusu olmuştur.'),
  ('Degas ve Caillebotte\'un tablolarında sık görülen yukarıdan ya da beklenmedik açılardan bakış, hangi modern deneyimi yansıtır?', 'Kentte balkonlardan ve yüksek pencerelerden bakmanın yeni bir alışkanlık olmasını', ['Ressamların göz hastalığını', 'Kiliselerin kubbelerinden bakılmasını', 'Uçaklardan çekilen fotoğrafları'], 'Haussmann apartmanlarının balkonları ve yüksek katları, kentlilere sokaklara yukarıdan bakma olanağı vermiş; bu bakış resimlere de geçmiştir.'),
  ('Bir ressam \'Eşyaların ne olduğunu bildiğim gibi değil, o an nasıl göründüklerine göre boyuyorum\' diyor. Bu yaklaşım hangi akımın temel tutumunu özetler?', 'İzlenimcilik', ['Akademik sanat', 'Nazarenler', 'Sentetizm'], 'İzlenimciler bilgiye değil görmeye dayanır; nesneyi zihnin bildiği haliyle değil, ışık altında göründüğü haliyle aktarmaya çalışır.'),
  ('Bir koleksiyoncu 1870\'lerde bir izlenimci tabloyu satın almaktan çekiniyor ve \'bitmemiş\' olduğunu söylüyor. Ressamın bakış açısından en uygun yanıt hangisi olurdu?', 'Tablo ışığın anlık etkisini verdiği anda amacına ulaşmıştır; daha fazla işlemek bu tazeliği bozardı', ['Tablo yalnız fotoğrafla birlikte satıldığında bitmiş sayılır', 'Tablo bir sonraki yıl Salon\'da bitirilecektir', 'Tablonun bitmesi için Akademinin onayı gerekir'], 'İzlenimciler \'bitmişlik\' ölçütünü yüzeyin pürüzsüzlüğünden değil, görsel izlenimin yakalanmasından alıyordu.'),
  ('Bir sanat tarihçisi Manet\'yi \'izlenimcilerin büyük ağabeyi\' olarak niteliyor. Hangisi bu nitelemeyi destekler?', 'Çağdaş konuları ve düz renk alanlarıyla genç ressamlara cesaret ve örnek olması', ['Yeni İzlenimciliği bulup Seurat\'ya öğretmesi', 'İzlenimci sergilerini baştan sona kendisinin düzenlemesi', 'İzlenimcilere ders vermek için bir okul açması'], 'Manet sergilere katılmasa da \'Çimenlerde Kahvaltı\' ve \'Olympia\' ile akademik kuralları sarsması, Batignolles çevresindeki gençler için yol açıcı olmuştur.'),
  ('Monet\'nin \'İzlenim, Gün Doğumu\' tablosu Le Havre limanını gösterir. Tabloya bakan biri sahnenin hangi özelliğini en belirgin biçimde görür?', 'Sisli mavi-gri bir atmosfer içinde parlayan turuncu güneş ve yansıması', ['Ayrıntılı çizilmiş gemi direkleri ve halatları', 'Kalabalık bir liman pazarındaki tüccarlar', 'Gece karanlığında yanan deniz feneri'], 'Tablo hızlı, ince vuruşlarla limanın sabah sisini ve suya düşen güneş yansımasını verir; ayrıntılar bilinçli olarak belirsizdir.'),
  ('Monet\'nin seri tablolarının (saman yığınları, kavaklar, katedral) tek tek değil bir arada sergilenmesini istemesinin nedeni nedir?', 'İzleyicinin ışığın zamanla nasıl değiştiğini karşılaştırarak görmesini sağlamak', ['Tabloların tek başına satılamayacak kadar küçük olması', 'Salonun duvarlarını doldurma zorunluluğu', 'Tabloları birbirinden ayırt edilemeyecek kadar aynı yapmak'], 'Dizi, aynı konunun farklı ışıklardaki varyasyonlarını yan yana sunarak zamanı ve algıyı resmin konusu haline getirir.'),
  ('Renoir\'ın tablolarındaki figürlerin teni çoğu zaman yaprakların arasından süzülen ışık lekeleriyle kaplıdır. Bu ayrıntı izlenimcilerin hangi ilgisini yansıtır?', 'Işığın nesnelerin yüzeyinde oluşturduğu değişken renk oyunlarını', ['Figürlerin hastalığını göstermeyi', 'Akademik anatomi kurallarını', 'Tenin tek renkle boyanması gerektiği inancını'], 'Renoir \'Moulin de la Galette\' gibi eserlerde gölge ve güneş lekelerini tenin ve giysilerin üzerinde titreştirerek açık havanın canlılığını verir.'),
  ('Bir sergi rehberi, Monet\'nin \'Kadınlar Bahçede\' tablosunda yüzlerin ayrıntısız, giysilerin ise güneş ve gölge lekeleriyle kurulduğunu söylüyor. Bu tercih hangi önceliği gösterir?', 'Kişilerin kimliğinden çok ışığın beyaz giysiler üzerindeki etkisini', ['Modellerin tanınmasını engelleyen bir sansür kaygısını', 'Tablonun bir moda dergisi için sipariş edilmesini', 'Yüz çizmeyi bilmeyen bir yardımcıya bırakılmasını'], 'Monet bu tabloda figürleri portre gibi değil, açık havadaki ışık ve gölgenin taşıyıcıları olarak ele almıştır.'),
  ('Pissarro\'nun izlenimciler arasında \'grubun babası\' olarak anılmasının en önemli nedeni hangisidir?', 'Yaşça büyük olup genç ressamlara yol gösteren, birleştirici bir kişiliğe sahip olması', ['Grubun bütün masraflarını tek başına karşılaması', 'Akademide profesörlük yapması', 'Grubun adını bulması'], 'Pissarro Cézanne, Gauguin ve van Gogh gibi pek çok genç ressama cömertçe yardım etmiş ve grup içindeki anlaşmazlıkları yumuşatmıştır.'),
  ('Degas\'nın bale sahnelerinde dansçıları çoğu zaman sahne üstündeki gösteri anında değil, prova, esneme ve dinlenme anlarında göstermesi neyi vurgular?', 'Gösterişin arkasındaki emeği, yorgunluğu ve disiplini', ['Balenin yalnız bir eğlence olduğunu', 'Dansçıların aristokrat aileden geldiğini', 'Opera binasının mimarisini'], 'Degas\'nın balerinleri esneyen, kaşınan, bekleyen genç kadınlardır; bu yaklaşım sahnenin büyüsünün arkasındaki gerçek emeği gösterir.'),
  ('Van Gogh bir mektubunda gördüğünü tam olarak yeniden üretmek yerine kendini güçlü biçimde ifade etmek için rengi keyfince kullandığını yazar. Bu tutum onu izlenimcilerden nasıl ayırır?', 'Renk, gözlemden çok duygunun anlatım aracı olur', ['Renkler tümüyle siyah-beyaza indirgenir, yalnız ton değerleri kalır', 'Resim yalnız bilimsel ölçümle yapılır', 'Konu antik mitolojiden seçilir'], 'İzlenimciler gördükleri ışığı aktarmaya çalışırken van Gogh rengi iç duygularını yoğunlaştırmak için abartır; bu tutum dışavurumculuğa uzanır.'),
  ('Van Gogh\'un \'Patates Yiyenler\' gibi Hollanda dönemi eserleri ile Arles dönemi eserleri karşılaştırıldığında en belirgin fark hangisidir?', 'Koyu toprak tonlarından parlak, doygun renklere geçiş', ['Manzara resminden tümüyle vazgeçip yalnızca portre yapmaya geçiş', 'Yağlı boyadan heykele geçiş', 'Büyük tuvalden minyatüre geçiş'], 'Paris\'te izlenimcileri ve Japon baskılarını tanıyan van Gogh, Güney Fransa\'nın güneşinde sarı, mavi ve turuncunun yoğun karşıtlıklarını kullanmıştır.'),
  ('Van Gogh\'un \'Yıldızlı Gece\' tablosundaki göğün girdaplar halinde kıvrılması en iyi nasıl yorumlanır?', 'Göğün görünüşünden çok ressamın coşkulu iç dünyasını yansıtması', ['Bir astronomi atlasının birebir kopyalanması', 'Gece fırtınasının ve rüzgârın meteorolojik açıdan bilimsel bir kaydı', 'Tabloya sonradan başka bir ressamın eklemesi'], 'Van Gogh gece göğünü gözlemle başlatmış ama onu hayal gücü ve duygu yüklü ritmik bir harekete dönüştürmüştür.'),
  ('Gauguin\'in ressamlara verdiği öğüt olarak bilinen \'Doğadan fazla kopya yapmayın; sanat bir soyutlamadır\' sözü hangi tutumu yansıtır?', 'Resmi doğanın taklidi değil, düşüncenin sentezi sayması', ['Doğadan hiç ilham alınmaması gerektiği', 'Yalnız fotoğraf kullanılması gerektiği', 'Doğanın her ayrıntısıyla titizce kopyalanması gerektiği'], 'Gauguin, gözlem yerine bellek ve hayal gücüyle sadeleştirilmiş, simgesel bir resim anlayışını savunmuştur.'),
  ('Gauguin\'in Brötanya\'yı ve ardından Tahiti\'yi seçmesinde ortak olan beklenti hangisidir?', 'Modern kentten uzak, \'ilkel\' ve saf sayılan bir ortam bulmak', ['Güzel Sanatlar Akademisi\'nde profesörlük kazanmak ve öğrenci yetiştirmek', 'Büyük sanayi kentlerini resmetmek', 'Saray siparişleri almak'], 'Gauguin önce Brötanya\'nın geleneksel köylü kültürüne, sonra Polinezya\'ya giderek uygarlığın yozlaştırmadığını düşündüğü bir dünyayı aramıştır.'),
  ('Cézanne\'ın resimlerinde nesnelerin ağırlıklı ve sağlam görünmesi, izlenimcilerin eriyen biçimleriyle karşılaştırıldığında neyi gösterir?', 'Işığın geçici etkisinden çok kalıcı yapıya ve hacme önem vermesini', ['Cézanne\'ın açık havada hiç çalışmamasını', 'Cézanne\'ın fotoğraftan kopya yapmasını', 'Cézanne\'ın yalnız siyah-beyaz çalışmasını'], 'Cézanne doğayı gözlemlemeyi sürdürmüş ama gördüğünü renk birimleriyle kurulan, mimari bir düzene dönüştürmüştür.'),
  ('Seurat\'nın bir tabloyu tamamlamak için yüzlerce eskiz ve çizim yapması, izlenimcilerin yöntemiyle karşılaştırıldığında hangi farkı gösterir?', 'Anlık izlenim yerine planlı bir kompozisyon arayışı', ['Açık havada tek oturuşta çalışma alışkanlığı', 'Çizimi tümüyle reddedip doğrudan tuvale boyayla başlama alışkanlığı', 'Renk kuramını bilmeme'], 'Seurat \'La Grande Jatte\' için onlarca yağlı eskiz ve desen yapmış, son tabloyu atölyede iki yıl boyunca titizlikle kurmuştur.'),
  ('Bir ressam yalnızca saf renkleri küçük noktalar halinde yan yana koyuyor ve karışımı izleyicinin gözüne bırakıyor. Paletinde iki rengi karıştırmamasının amacı nedir?', 'Renklerin parlaklığını yitirmeden gözde karışması', ['Pahalı boyadan tasarruf etmek ve tabloyu daha ucuza mal etmek', 'Tablonun daha hızlı kurumasını sağlamak', 'Renk körü izleyicilere yardımcı olmak'], 'Yeni İzlenimciler boyayı fiziksel olarak karıştırmanın rengi bulandırdığını düşünmüş; ışıkla gözde karışan renklerin daha canlı kalacağına inanmıştır.'),
  ('Toulouse-Lautrec\'in Montmartre\'ın kabare, sirk ve genelevlerini içeriden, yargılamadan resmetmesi hangi tutumu yansıtır?', 'Toplumun kenarındaki insanlara yakın bir tanık gibi bakması', ['Bu mekânları kınayan ahlaki bir vaaz vermesi', 'Yalnız soylu çevrelerin eğlencelerini göstermesi', 'Hayal ürünü masal dünyaları kurması'], 'Lautrec bu ortamların gerçek bir müdavimiydi; dansçıları, şarkıcıları ve kadınları acımasız ama sevecen bir gözlemle göstermiştir.'),
  ('Prerafaelitlerin tablolarındaki parlak, mücevher gibi renklerin bir nedeni de beyaz bir zemine, bazen hâlâ ıslak beyaz bir katmanın üzerine boyamalarıdır. Bu teknik hangi sonuca hizmet eder?', 'Renklerin ışıltılı ve saydam görünmesi', ['Tabloların daha karanlık görünmesi', 'Boyanın daha az tutması', 'Fırça izlerinin daha kaba olması'], 'Beyaz zemin, ince renk katmanlarından ışığın yansımasını sağlar; Prerafaelitler akademinin koyu zeminli resimlerine karşı parlak bir yüzey arıyordu.'),
  ('Prerafaelit bir tabloyu inceleyen bir öğrenci her yaprağın, çiçeğin ve kumaş kıvrımının en küçük ayrıntısına dek resmedildiğini görüyor. Bu titizlik hangi ilkeden kaynaklanır?', 'Doğaya ve gözleme mutlak sadakat', ['Fotoğrafın yasaklanması', 'Çabuk satış yapma isteği', 'Akademinin yalnız ayrıntılı eser kabul etmesi'], 'Prerafaelitler, Ruskin\'in de savunduğu gibi, doğayı seçmeden ve idealleştirmeden en ince ayrıntısıyla gözlemlemeyi ahlaki bir görev saymıştır.'),
  ('Prerafaelitlerin konularını çoğu zaman Shakespeare, Dante, Tennyson ve Kral Arthur efsanelerinden seçmesi hangi eğilimi gösterir?', 'Edebiyata ve Orta Çağ\'a duyulan romantik ilgiyi', ['Sanayi devrimini yüceltme isteğini', 'Antik Roma tarihine bağlılığı', 'Gündelik kent yaşamını belgeleme amacını'], 'Prerafaelitler, Orta Çağ ve edebi kaynaklardan beslenerek modern dünyanın sıradanlığına karşı şiirsel ve ahlaki anlamlar arıyordu.'),
  ('Sembolist bir eserde beyaz zambak, haşhaş ya da kafatası gibi nesnelerin bulunması, izleyiciden hangi okuma biçimini bekler?', 'Nesneleri gizli anlamlar taşıyan işaretler olarak okumasını', ['Nesnelerin yalnız dekor olduğunu kabul etmesini', 'Nesnelerin piyasadaki fiyatını ve ne kadara satılabileceğini tahmin etmesini', 'Nesnelerin bilimsel adlarını öğrenmesini'], 'Sembolizmde nesneler saflık, uyku, ölüm gibi kavramları çağrıştıran simgelerdir; resim bir \'okuma\' gerektirir.'),
  ('Bir öğrenci 19. yüzyıl sonunda hem Sembolizmin hem de Postizlenimciliğin aynı yıllarda var olmasını çelişkili buluyor. Öğretmenin en uygun açıklaması hangisidir?', 'İkisi de görünen dünyaya bağlılığı aşma arayışının farklı biçimleridir', ['İkisi tümüyle aynı akımın iki adıdır', 'Biri yalnızca Fransa\'da, öteki yalnızca Japonya\'da ve Çin\'de gelişmiştir', 'Biri resimde, öteki yalnızca mimaride görülür'], 'Gauguin gibi sanatçılar her iki çevreyle de ilişkilidir; ortak nokta, salt görsel izlenim yerine anlam, duygu ve yapıyı öne çıkarmaktır.'),
  ('Munch\'un tablolarındaki kıvrılan çizgiler, gerçek dışı renkler ve yalnız figürler 20. yüzyılda hangi akımın habercisi sayılır?', 'Dışavurumculuk', ['Fotogerçekçilik', 'Minimalizm', 'Neoklasisizm'], 'Munch\'un iç dünyayı bozulmuş biçim ve yoğun renklerle dışa vurması, Alman dışavurumcularının doğrudan esin kaynağı olmuştur.'),
  ('Bir eleştirmen \'Bu tablolar bir ressamın gözüyle değil, bir bilim insanının sabrıyla yapılmış\' diyor. Bu yorum en çok hangi ressamın eserlerine uyar?', 'Georges Seurat', ['Paul Gauguin', 'Vincent van Gogh', 'Edvard Munch'], 'Seurat optik ve renk kuramlarını sistemli biçimde uygulamış, yüzeyi hesaplı noktalarla kurmuştur.'),
  ('Gauguin ile van Gogh\'un Arles\'daki ortak yaşamı neden kısa sürede kötü bitmiştir?', 'Sanat anlayışları ve kişilikleri çatışmış, gerilim krize varmıştır', ['İkisi de Paris\'te büyük bir devlet siparişi alıp Arles\'dan ayrılmak zorunda kalmıştır', 'Theo onları ayrı ülkelere göndermiştir', 'Sarı Ev bir selde yıkılmıştır'], 'Gauguin bellekten ve hayal gücünden, van Gogh doğadan çalışmayı savunuyordu; tartışmalar Aralık 1888\'deki kulak olayıyla sona ermiştir.'),
  ('Turner ile Constable\'ın manzara anlayışları karşılaştırıldığında hangisi doğrudur?', 'Constable sakin kırsal gözleme, Turner ışığın dramatik gücüne yönelmiştir', ['İkisi de yalnızca deniz savaşlarını ve donanma törenlerini resmetmiştir', 'Constable soyut, Turner fotoğrafik resim yapmıştır', 'İkisi de manzarayı hiç resmetmemiştir'], 'Constable Suffolk\'un değirmenlerini ve bulutlarını sevgiyle izlerken Turner fırtına, yangın ve buharla yüce bir doğa tablosu kurmuştur.'),
  ('Goya\'nın \'3 Mayıs 1808\' tablosunda kurşuna dizen askerlerin yüzleri görünmez, kurbanların yüzleri ise açıkça görünür. Bu tercih hangi etkiyi yaratır?', 'Askerleri yüzsüz bir makineye, kurbanları acı çeken bireylere dönüştürür', ['İzleyicinin askerlerle özdeşleşmesini sağlar', 'Sahneyi kasabanın neşeli bir panayır şenliğine çevirip gerilimi yok eder', 'Olayın hangi ülkede geçtiğini gizler'], 'Sırtı dönük, sıra halindeki askerler yüzsüz bir şiddet düzenini, ışık altındaki kurbanlar ise insanca korkuyu temsil eder.'),
  ('Reddedilenler Salonu\'nun (1863) uzun vadede sanat dünyasına etkisi en iyi nasıl değerlendirilir?', 'Jürinin tek yetkili hakem olmadığı fikrini güçlendirmiştir', ['Akademinin gücünü kalıcı olarak artırmıştır', 'Paris\'te resim sergilerini tümüyle sona erdirip yalnız müzeleri bırakmıştır', 'İzlenimcilerin Salon\'a girmesini zorunlu kılmıştır'], 'Halkın reddedilen eserleri görmesi, Salon\'un yargılarının tartışılabileceğini göstermiş; bu da 1874\'teki bağımsız izlenimci sergisi gibi girişimlere zemin hazırlamıştır.'),
  ('Bir ressam 1860\'larda Salon\'dan sürekli reddediliyor. Bu ressamın kariyeri için reddedilmenin en somut sonucu ne olurdu?', 'Alıcılara ve eleştirmenlere ulaşacağı başlıca vitrini yitirmek', ['Resim yapmasının yasaklanması', 'Akademiden teselli ödülü ve Roma\'da çalışma bursu alması', 'Eserlerinin devlet tarafından satın alınması'], '19. yüzyıl ortasında Salon, bir sanatçının tanınmasının, sipariş ve satış almasının neredeyse tek yoluydu.'),
  ('19. yüzyılda resim satıcılarının ve özel galerilerin güç kazanması sanatçıların durumunu nasıl değiştirmiştir?', 'Salon onayı olmadan da alıcıya ulaşılabilir olmuştur', ['Sanatçılar yalnızca kiliseye ve manastırlara çalışmak zorunda kalmıştır', 'Resim satışları yasaklanmıştır', 'Sanatçılar eserlerini imzalayamaz olmuştur'], 'Durand-Ruel ve Vollard gibi satıcılar, Salon dışındaki sanatçılara sergi, düzenli gelir ve uluslararası pazar sağlamıştır.'),
  ('Bir öğrenci, 19. yüzyıl kadın ressamlarının Güzel Sanatlar Okulu\'ndan uzun süre dışlanmasının sanat eğitimleri açısından en büyük dezavantajının ne olduğunu araştırıyor. En doğru yanıt hangisidir?', 'Çıplak canlı model çalışmasından ve tarih resminden uzak tutulmaları', ['Boyaya erişememeleri', 'Yalnızca heykel yapabilmeleri ve resim atölyelerine hiç girememeleri', 'Resimlerini imzalayamamaları'], 'Akademik eğitimin temeli olan çıplak model çalışması kadınlara kapalıydı; bu da en saygın tür sayılan tarih resmini yapmalarını zorlaştırıyordu.'),
  ('Bir sergi küratörü \'Japon baskıları olmasaydı van Gogh, Degas ve Toulouse-Lautrec\'in kompozisyonları çok farklı olurdu\' diyor. Bu yargıyı en iyi destekleyen kanıt hangisidir?', 'Üçünün eserlerinde düz renk, kesik kadraj ve yüksek bakışın görülmesi', ['Üçünün de Japonya\'da yaşamış olması', 'Üçünün de yalnız siyah-beyaz çalışması', 'Üçünün de Japonca bilip Japon ustalardan mektupla ders alması'], 'Japon baskılarının biçimsel özellikleri bu sanatçıların kompozisyonlarında açıkça görülür; hiçbiri Japonya\'ya gitmemiştir.'),
  ('Bir öğrenci \'Realizm ile İzlenimcilik aynı şeydir; ikisi de gerçeği resmeder\' diyor. Bu yargıyı düzelten en uygun açıklama hangisidir?', 'Realizm toplumsal gerçekliğe, İzlenimcilik görmenin anlık gerçekliğine odaklanır', ['İzlenimcilik yalnızca mitolojik konuları ve antik tanrıları resmetmiştir', 'Realizm yalnız heykelle sınırlıdır', 'İkisi de yalnız gece sahneleri resmeder'], 'Courbet ve Millet emekçi yaşamını ağırlıklı ve maddesel biçimde gösterirken izlenimciler ışık, renk ve anı yakalamaya yönelmiştir.'),
  ('Bir eserde bir kadın kahvede tek başına, önünde bir bardak içkiyle dalgın oturuyor; sahne yukarıdan ve kenara kaymış bir açıdan görülüyor. Bu eser en büyük olasılıkla kimin üslubunu yansıtır?', 'Edgar Degas', ['Jean-Baptiste Camille Corot', 'William Blake', 'John Constable'], 'Kafede yalnızlık konusu ve alışılmadık, kesik kadraj Degas\'nın modern yaşam sahnelerinin tipik özelliğidir.'),
  ('Bir öğrenci Prerafaelitleri \'modern\' sayıp saymamakta kararsızdır. Hangisi onların hem geçmişe dönük hem de yenilikçi yanını en iyi açıklar?', 'Eski ustaları örnek alırken akademiye başkaldırıp çağdaş konulara da eğilmeleri', ['Yalnızca Rönesans eserlerini kopyalamaları', 'İzlenimcilerle aynı teknikleri kullanıp onlarla Paris\'te ortak sergi açmaları', 'Fotoğrafı resmin yerine koymaları'], 'Prerafaelitler geçmişe öykünse de akademiye başkaldırmış, \'Uyanan Vicdan\' ve \'İngiltere\'nin Son Görüşü\' gibi eserlerle çağdaş sorunlara da yönelmiştir.'),
  ('Bir eleştirmen Courbet\'nin \'Bana bir melek gösterin, onu resmedeyim\' sözünü hangi resim anlayışına karşı bir tavır olarak yorumlar?', 'İdeal ya da kutsal varlıkları resmeden akademik ve dinsel resme', ['Sanayi devrimini resmeden Realist resme', 'Gündelik köylü yaşamını gösteren resme', 'Açık havada doğrudan gözleme dayanan manzara resmine'], 'Söz, ressamın yalnız gözle görülen gerçekliği resmetmesi gerektiği fikrini, idealize ve hayali konulara karşı alaycı biçimde savunur.'),
  ('Constable\'ın \'Saman Arabası\'nda sığ suda duran araba, köpek ve değirmen evi gibi sıradan öğelerin büyük bir tuvalde yer alması hangi tutumu gösterir?', 'Gündelik kırsal yaşamın büyük sanata konu olabileceğini', ['Manzaranın yalnızca mitolojik öykülerin arka planı olduğunu', 'Kırsal yaşamın küçümsenmesi gerektiğini', 'Resmin yalnız krallara ayrıldığını'], 'Constable kendi doğduğu yerin sıradan manzarasını tarih resmi kadar değerli bir konu olarak sunmuş; bu tutum Realizme ve izlenimciliğe giden yolu açmıştır.'),
  ('Bir resim öğretmeni öğrencilerinden Delacroix ile Ingres\'in yaklaşımını tek cümleyle özetlemelerini istiyor. Hangisi en isabetlidir?', 'Delacroix tutkuyu renkle, Ingres ideal güzelliği çizgiyle aramıştır', ['Delacroix yalnız heykel, Ingres yalnız mimarlıkla uğraşmıştır', 'İkisi de izlenimci sergilere katılıp açık havada resim yapmıştır', 'Delacroix çizgiyi, Ingres rengi yüceltmiştir'], 'Yüzyılın ilk yarısındaki \'renk ve çizgi\' tartışması Delacroix\'nın romantik coşkusu ile Ingres\'in klasik disiplini arasında yaşanmıştır.'),
  ('Bir eserde gerçek bir manzara yerine, renkleri yoğunlaştırılmış ve biçimleri sadeleştirilmiş, neredeyse süsleme gibi düzlemsel bir sahne var. Ressam izleyiciden \'gördüğünü değil, hissettiğini\' anlamasını bekliyor. Bu tutum hangi ressamın anlayışına en yakındır?', 'Paul Gauguin', ['Gustave Caillebotte', 'Alfred Sisley', 'Ernest Meissonier'], 'Gauguin\'in Sentetizmi, gözlemi bellek ve duygu süzgecinden geçirip düz renk alanlarıyla simgesel bir dile dönüştürür.'),
  ('Bir müzede \'Bu salondaki eserler 1874-1886 arasında Paris\'te düzenlenen sekiz bağımsız grup sergisinden seçilmiştir\' yazıyor. Bu salonda büyük olasılıkla hangi akımın eserleri vardır?', 'İzlenimcilik', ['Romantizm', 'Prerafaelitizm', 'Nazarenler'], 'Sekiz bağımsız sergi izlenimcilerin 1874\'te başlayıp 1886\'da sona eren grup sergileridir.'),
  ('Bir ressam İngiltere\'de 1850\'lerde parlak renklerle, Shakespeare\'den bir sahneyi her yaprağı tek tek çizilmiş bir doğa içinde resmediyor. Bu ressam büyük olasılıkla hangi gruptandır?', 'Prerafaelitler', ['Barbizon Okulu', 'Nabiler', 'Yeni İzlenimciler'], 'Parlak renk, edebi konu ve titiz doğa ayrıntısı, 1848\'de kurulan İngiliz Prerafaelit grubunun belirgin özellikleridir.'),
  ('Bir sergide \'çağdaş bir köylü kadını hiçbir süsleme yapmadan tarlada çalışırken\' gösteren bir tablo ile \'antik bir tanrıçayı kusursuz bir tenle\' gösteren bir tablo yan yana. Bu tablolar sırasıyla hangi anlayışları temsil eder?', 'Realizm ve akademik sanat', ['Sembolizm ve Romantizm', 'İzlenimcilik ve Prerafaelitizm', 'Akademik sanat ve Realizm'], 'Sıradan emekçiyi idealleştirmeden göstermek Realizme, mitolojik güzelliği pürüzsüz bir yüzeyle sunmak ise akademik Salon sanatına özgüdür.'),
  ('Bir öğrenci izlenimci bir eserde fırça vuruşlarının açıkça görülmesini \'özensizlik\' olarak niteliyor. Öğretmen hangi yanıtla öğrencinin bakışını düzeltebilir?', 'Görünür fırça izi, değişen ışığı yakalama çabasının bilinçli bir göstergesidir', ['Fırça izleri, tablonun yarım kaldığını ve ressamın onu bitirmeye vakit bulamadığını gösterir', 'İzlenimciler fırça yerine parmak kullanmıştır', 'Fırça izleri zamanla kendiliğinden oluşmuştur'], 'Akademik pürüzsüzlüğün tersine, izlenimciler fırça izini canlılık ve içtenlik işareti olarak bırakmıştır.'),
  ('Bir eserde ön planda devasa, kabaran bir dalga, uzakta küçük bir fener ve sisli bir gökyüzü var; izleyici doğanın gücü karşısında ürperiyor. Ressamın amacı en çok hangi duyguyu uyandırmaktır?', 'Yücelik', ['Neşe ve şenlik coşkusu', 'Tatlı bir hüzün', 'Sakin bir huzur'], 'Doğanın insanı aşan gücünün yarattığı korkuyla karışık hayranlık, Romantik estetikte \'yücelik\' olarak adlandırılır.'),
  ('Romantizm ile Realizm arasındaki temel fark hangisidir?', 'Romantizm duygu ve hayal gücünü, Realizm gündelik gerçekliği öne çıkarır', ['Romantizm yalnızca heykel, Realizm ise yalnızca resim alanında görülmüştür', 'Romantizm 20. yüzyılda, Realizm 17. yüzyılda doğmuştur', 'İkisi arasında hiçbir fark yoktur'], 'Romantik ressamlar egzotik, tarihsel ve tutkulu konuları seçerken realistler kendi çağlarının sıradan yaşamını resmetmiştir.'),
  ('Bir resim öğretmeni öğrencilerine bir saman yığınını sabah ve akşam ayrı ayrı boyamalarını, her seferinde yalnız gördükleri renkleri kullanmalarını söylüyor. Bu alıştırma hangi ressamın yöntemini taklit eder?', 'Claude Monet', ['Jean-Auguste-Dominique Ingres', 'William Blake', 'Gustave Moreau'], 'Monet, saman yığınlarını günün ve mevsimin farklı ışıklarında defalarca resmederek ışığın nesneyi nasıl dönüştürdüğünü göstermiştir.'),
  ('Bir resim öğretmeni öğrencilerine, bir natürmortta elmaları, sürahiyi ve masa örtüsünü basit geometrik kütlelere indirgemelerini ve renk lekeleriyle hacim kurmalarını söylüyor. Bu alıştırma hangi ressamın yaklaşımından esinlenmiştir?', 'Paul Cézanne', ['Henri de Toulouse-Lautrec', 'Edward Burne-Jones', 'Jean-Léon Gérôme'], 'Cézanne natürmortlarında nesneleri renk modülasyonuyla hacim kazanan sağlam biçimlere dönüştürmüştür.'),
  ('Bir resim öğretmeni öğrencilerine ayçiçeklerini kalın boyayla, kıvrımlı fırça vuruşlarıyla ve yoğun sarı tonlarla resmetmelerini öneriyor. Bu öneri hangi ressamın üslubuna dayanır?', 'Vincent van Gogh', ['Edgar Degas', 'John Everett Millais', 'Camille Corot'], 'Kalın impasto, kıvrımlı vuruş ve yoğun sarılar van Gogh\'un Arles dönemi ayçiçeklerini çağrıştırır.'),
  ('Bir öğrenci Seurat\'nın noktacı yöntemini denemek istiyor. Hangisi bu yönteme uygun bir uygulamadır?', 'Saf renkleri noktalar halinde yan yana koyup karışımı göze bırakmak', ['Renkleri paletinde iyice karıştırıp tek düze sürmek', 'Yalnız siyah mürekkeple çizgi çizmek', 'Boyayı palet bıçağıyla kalın katmanlar halinde sıvamak'], 'Noktacılıkta renkler fiziksel olarak karıştırılmaz; ayrık noktalar uzaktan optik olarak kaynaşır.'),
  ('Bir öğrenci \'Sembolistler gerçekçi resim yapmadı, çünkü çizmeyi bilmiyorlardı\' diyor. Bu yargı neden yanlıştır?', 'Çoğu akademik eğitimliydi; gerçekçiliği bilinçli olarak aşmışlardır', ['Sembolistler yalnız fotoğraf çekmiştir', 'Sembolistler resim yapmamış, yalnızca şiir ve manifesto yazmakla yetinmiştir', 'Sembolistler yalnız mimarlıkla uğraşmıştır'], 'Moreau, Puvis de Chavannes ve Khnopff gibi sanatçılar güçlü bir teknik birikime sahipti; amaçları görüneni değil, düşünceyi göstermekti.'),
  ('Bir eserde Kral Arthur efsanesinden bir kadın, süslü bir kayıkta, çevresinde mumlar ve işlemeli örtülerle hüzünlü bir yolculuğa çıkıyor; ayrıntılar son derece titiz. Bu eser en çok hangi geleneğe uyar?', 'Prerafaelit geleneği', ['İzlenimcilik', 'Barbizon Okulu manzarası', 'Yeni İzlenimcilik'], 'Arthur efsaneleri, edebi konular ve titiz ayrıntı Prerafaelitlerin ve izleyicilerinin, örneğin Waterhouse\'un, tipik özellikleridir.'),
  ('19. yüzyılın ortasında fotoğrafın yaygınlaşması portre ressamlarını en çok hangi yönden etkilemiştir?', 'Hızlı ve ucuz portre ihtiyacını fotoğraf karşılamaya başlamıştır', ['Portre siparişleri birden on katına çıkmıştır', 'Ressamların portre yapması yasaklanmıştır', 'Fotoğraf yalnızca manzara çekebildiği için portreyi etkilememiştir'], 'Orta sınıf, ressama ödeyeceğinden çok daha ucuza fotoğraf stüdyolarında portre yaptırmaya başlamış; bu da küçük portre ressamlarının işini azaltmıştır.'),
  ('Bir öğrenci \'Postizlenimcilik bir grup ya da dernek adıdır\' diyor. Bu yargıyı düzelten bilgi hangisidir?', 'Terim, 1910\'da bir eleştirmenin geriye dönük olarak koyduğu bir addır', ['Postizlenimciler 1874\'te bir anonim şirket kurmuştur', 'Postizlenimcilik yalnızca Japonya\'da ve Uzak Doğu\'da kullanılan bir terimdir', 'Terim Kraliyet Akademisi\'nin resmi bölümlerinden biridir'], 'Cézanne, van Gogh, Gauguin ve Seurat hiçbir zaman bu adla bir grup kurmamıştır; \'Postizlenimcilik\' Roger Fry\'ın sonradan koyduğu bir etikettir.'),
  ('Bir sanat öğrencisi \'Manet bir izlenimcidir\' diyor, öğretmeni ise \'Tam olarak değil\' diye yanıtlıyor. Öğretmenin çekincesi en çok neye dayanır?', 'Manet\'nin grup sergilerine katılmayıp Salon\'da tanınmayı sürdürmesi', ['Manet\'nin hiç renk kullanmaması', 'Manet\'nin yalnız heykel yapması', 'Manet\'nin hayatının büyük bölümünü İngiltere\'de geçirip orada sergi açması'], 'Manet izlenimcilerle dostluk kurmuş ve bir dönem açık havada çalışmış, ama bağımsız sergilere katılmayıp resmi Salon\'da başarı aramıştır.'),
  ('Bir ressam tablolarında Paris\'in kafelerinde, opera localarında ve bulvarlarında gezinen şık kentlileri gösteriyor. Bu konu seçimi hangi akımın ilgileriyle en çok örtüşür?', 'İzlenimcilik', ['Nazarenler', 'Romantik tarih resmi', 'Barbizon Okulu'], 'Modern kent yaşamının eğlence mekânları ve kalabalıkları izlenimcilerin, özellikle Degas, Renoir ve Caillebotte\'un başlıca konularıdır.'),
  ('Gauguin\'in \'Sarı İsa\' tablosunda ağaçların kırmızı, tarlaların sarı boyanması en iyi nasıl açıklanır?', 'Rengin doğayı taklit etmek yerine duyguyu ve inancı iletmesi', ['Ressamın renk körü olması', 'Tablonun sonbaharda tarlalarda çıkan büyük bir yangını belgesel olarak göstermesi', 'Boyaların zamanla renk değiştirmesi'], 'Sentetist anlayışta renk, gözlenen gerçeklikten bağımsızlaşarak simgesel ve duygusal bir anlam taşır.'),
  ('Bir öğrenci Barbizon ressamlarını \'Realizmin manzaradaki karşılığı\' olarak tanımlıyor. Bu tanımı en iyi destekleyen gözlem hangisidir?', 'Süs yerine sıradan Fransız kırsalını olduğu gibi gözlemlemeleri', ['Yalnız deniz savaşları resmetmeleri', 'Gotik kiliseleri ve Orta Çağ şatolarını yeniden inşa eder gibi ayrıntılı çizmeleri', 'Japon baskılarını kopyalamaları'], 'Barbizon ressamları, Courbet ve Millet\'nin figürlerde yaptığını manzarada yapmış; idealize edilmemiş yerel doğayı resmetmiştir.'),
  ('Bir sanat tarihçisi Géricault\'nun \'Medusa\'nın Salı\'nı \'kahramansız bir tarih resmi\' olarak niteliyor. Bu nitelemenin dayanağı hangisidir?', 'Kral ya da komutan yerine isimsiz kazazedeleri merkeze alması', ['Tablonun hiç insan figürü içermemesi', 'Tablonun mitolojik bir öyküyü anlatması', 'Tablonun küçük boyutlu bir eskiz olarak bırakılıp Salon\'a hiç gönderilmemesi'], 'Géricault tarih resminin dev ölçeğini sıradan, acı çeken insanların gerçek bir felaketine ayırmış; bu tutum Romantizmle Realizm arasında bir köprü kurar.'),
  ('Courbet\'nin \'Ornans\'ta Cenaze\'sinde figürlerin bir çizgi boyunca, neredeyse hiyerarşisiz biçimde sıralanması hangi düşünceyi destekler?', 'Köylülerin eşit ağırlıkta gösterilmesini', ['Bir kralın cenazesinin görkemini', 'Rahiplerin ve belediye başkanının halktan üstün olduğunu', 'Ölen kişinin bir aziz olduğunu'], 'Merkezî bir kahraman yerine yan yana dizilmiş taşralıların hepsine yer veren düzen, Courbet\'nin demokratik ve gerçekçi bakışını yansıtır.'),
  ('Daumier\'nin \'Üçüncü Mevki Vagon\' tablosunda yolcuların birbirine bakmadan, yorgun ve sessiz oturması hangi modern deneyimi yansıtır?', 'Kalabalık içindeki yalnızlığı ve yorgunluğu', ['Lüks yolculukların keyfini', 'Bir kilise ayinine katılan cemaati', 'Savaştan dönen askerlerin zafer sevincini'], 'Daumier, sanayi çağının yeni ulaşım aracında yoksul yolcuların sıkışık ama birbirine kapalı yaşamını sessiz bir dayanışma ve hüzünle gösterir.'),
  ('Bir öğrenci 19. yüzyılın başlıca akımlarını \'kim neye karşı çıktı\' sorusuyla özetlemek istiyor. Hangisi doğru bir eşleştirmedir?', 'Realizm, Romantizmin hayal gücüne ve geçmişe kaçışına karşı çıkmıştır', ['İzlenimcilik, Yeni İzlenimciliğe karşı doğmuştur', 'Romantizm, İzlenimciliğe ve onun açık hava resmine tepki olarak ortaya çıkmıştır', 'Postizlenimcilik, Realizmden önce gelmiştir'], 'Realizm, Romantizmin egzotik ve geçmişe dönük konularına karşı çağdaş ve görünür gerçekliği savunmuştur; diğer seçeneklerde kronoloji yanlıştır.'),
  ('1880\'lerde Gauguin ve genç ressamların Brötanya\'daki Pont-Aven köyüne yerleşmesinin başlıca nedenlerinden biri hangisidir?', 'Ucuz yaşam ve \'ilkel\' sayılan geleneksel köy kültürü', ['Köyde Paris akademisine bağlı büyük bir resim okulunun ve müzenin bulunması', 'Köyün sanayi fabrikalarıyla dolu olması', 'Köyün Paris\'in tam merkezinde olması'], 'Pont-Aven hem ucuzdu hem de Bretonların dindar ve geleneksel yaşamı Gauguin\'e kentten uzak, saf bir dünya sunuyordu.'),
  ('Nabilerin resimlerinde derinlik yanılsamasının azaltılıp yüzeyin desenli bir halı gibi düzenlenmesi en çok neyi vurgular?', 'Resmin düz bir yüzey olduğunu ve süsleme değerini', ['Perspektif kurallarına kesin bağlılığı', 'Fotoğrafik gerçekçiliği', 'Dinsel anlatının tarihsel doğruluğunu'], 'Nabiler Maurice Denis\'nin tanımına uygun olarak resmi bir pencere değil, renklerle örülmüş bir yüzey olarak ele almıştır.'),
  ('Toulouse-Lautrec\'in figürlerini çoğu zaman birkaç hızlı, keskin çizgiyle ve abartılmış yüz ifadeleriyle göstermesi hangi alandaki deneyimiyle ilişkilidir?', 'Karikatür ve hızlı çizim alışkanlığı', ['Fresk restorasyonu', 'Mimari çizim', 'Bilimsel botanik çizimi'], 'Lautrec kafelerde ve kabarelerde hızlı eskizler yapar, kişilerin karakterini birkaç çizgiyle yakalardı; bu yaklaşım karikatüre yakındır.'),
  ('Rus Gezginler ressamlarının sergilerini kentten kente taşıması hangi amaca hizmet ediyordu?', 'Sanatı dar başkent çevresinden geniş halka ulaştırmak', ['Eserleri yalnız Çar\'a göstermek', 'Eserleri sansürden kaçırıp gizlice yurt dışındaki koleksiyonculara satmak', 'Akademiye girmek için sınav yapmak'], 'Gezginler sanatı toplumsal bir eğitim ve bilinçlendirme aracı olarak görmüş, taşra kentlerinde de sergi açmıştır.'),
  ('Hudson Nehri Okulu ressamlarının Amerika\'nın vahşi doğasını görkemli biçimde resmetmesi, dönemin hangi ulusal duygusuyla ilişkilendirilir?', 'Ulusal kimliği tarihsel geçmiş yerine el değmemiş doğada bulma isteği', ['Avrupa\'daki saraylara özlem', 'Hızla büyüyen sanayi kentlerine, fabrikalara ve demiryollarına duyulan hayranlık', 'Antik Roma\'ya dönme isteği'], 'Avrupa\'nın katedralleri ve antik harabeleri yoktu; Amerikan ressamları vahşi doğayı ulusun \'tapınağı\' ve kimliği olarak yüceltmiştir.'),
  ('Winslow Homer ile Thomas Eakins\'in ortak özelliği hangisidir?', 'Amerikan yaşamını idealize etmeyen bir gerçekçilikle resmetmeleri', ['İkisinin de yalnız Paris\'te yaşayıp Amerika\'yı hiç görmemesi', 'İkisinin de soyut resim yapması', 'İkisinin de Prerafaelit Kardeşliğe üye olması'], 'Homer deniz ve kırsal yaşamı, Eakins ise sporu, tıbbı ve portreyi gözleme dayalı yalın bir gerçekçilikle işlemiştir.'),
  ('Akademik resim eğitiminde öğrencilerin uzun süre alçı heykel kopyası çizmesinin amacı neydi?', 'İdeal oranları ve ışık-gölgeyi sabit bir modelde öğrenmek', ['Heykeltıraş olmak için hazırlık yapmak', 'Renk kuramını, tamamlayıcı renkleri ve optik karışımı ayrıntılı biçimde öğrenmek', 'Fotoğraf çekmeyi öğrenmek'], 'Antik heykellerin alçı kopyaları hem \'ideal güzellik\' örneği hem de kıpırdamayan, ışığı sabit tutulabilen modellerdi.'),
  ('Bir öğrenci Munch\'un \'Hasta Çocuk\' tablosunun yüzeyinin kazınmış ve yeniden boyanmış olmasını fark ediyor. Bu yüzey en iyi nasıl yorumlanır?', 'Ressamın acı anıyla sürekli boğuşmasının izi', ['Tablonun taşınırken zarar görmesi', 'Ressamın boya bulamaması', 'Ressamın boya bulamayıp aynı tuvali başka bir resim için yeniden kullanması'], 'Munch, kız kardeşinin ölümünü defalarca kazıyıp yeniden boyayarak resmetmiş; yüzeydeki yaralar anının duygusal yükünü maddeye dönüştürür.'),
  ('Bir müze gezisinde öğrenciler \'Bu eserde ressam, çiçek açmış bir meyve bahçesini ve kırmızı çatılı köy evlerini sakin, sıcak ve küçük fırça vuruşlarıyla resmetmiş; kalabalık yok, köylüler işinde\' diye not alıyor. Bu betimleme en çok hangi ressama uyar?', 'Camille Pissarro', ['Gustave Moreau', 'Jean-Léon Gérôme', 'Dante Gabriel Rossetti'], 'Köy yaşamı, meyve bahçeleri ve sıcak, sakin izlenimci dokunuş Pissarro\'nun Pontoise ve Éragny eserlerinin tipik özellikleridir.'),
  ('Bir öğrenci \'Realizm yalnızca Fransa\'da görüldü\' diyor. Hangisi bu yargının yanlış olduğunu gösterir?', 'Rusya, Almanya ve ABD\'de de önemli gerçekçi sanatçıların bulunması', ['Realizmin yalnız Japonya\'da doğması', 'Fransa\'da hiç realist ressam yetişmemiş olması ve akımın yalnızca İngiltere\'de görülmesi', 'Realizmin bir heykel akımı olması'], 'Realizm 19. yüzyılın ikinci yarısında birçok ülkede, yerel toplumsal koşullara göre farklı biçimler almıştır.'),
  ('Bir öğrenci Monet\'nin \'Saint-Lazare Garı\' dizisini \'yalnızca bir istasyon resmi\' olarak görüyor. Hangi yorum diziye daha derin bir anlam kazandırır?', 'Buhar, cam ve demirle modern çağın hızını ve sanayi gücünü resmin konusu yapması', ['İstasyonun mimari planını belgelemek için yapılması', 'Demiryolu şirketinin reklamı olması', 'Gece karanlığında çekilmiş fotoğrafların kopyası olması'], 'Monet, modern yaşamın simgesi olan treni ve garı ışık ve buhar etkileri üzerinden yorumlayarak sanayi çağına bir izlenimci bakış getirmiştir.'),
  ('19. yüzyıl boyunca Romantizm, Realizm, İzlenimcilik ve Postizlenimcilik birbirini izlemiştir. Bu sürecin genel yönünü en iyi hangisi özetler?', 'Resmin konuyu anlatmaktan kendi araçlarını sorgulamaya yönelmesi', ['Resmin giderek daha çok dinsel konulara dönmesi', 'Resmin fotoğrafla tümüyle yer değiştirmesi', 'Resmin tek bir akademik üslupta birleşip bütün ülkelerde aynılaşması'], 'Yüzyıl boyunca konu ve anlatının ağırlığı azalmış, ressamlar algıyı, rengi ve resmin yapısını öne çıkararak modern sanatın zeminini hazırlamıştır.'),
  ('Constable\'ın eşinin ölümünden sonra yaptığı, harabe bir kalenin fırtınalı bir gökyüzü altında yalnız durduğu 1829 tarihli eserinde manzara hangi işlevi üstlenir?', 'Ressamın yasını ve iç karanlığını yansıtan bir duygu aynası', ['Bir askeri kalenin mühendislik planı', 'Bir kraliyet şenliğinin arka planı', 'Bir tarım ürünleri katalogu'], '\'Hadleigh Kalesi\' çoğunlukla Constable\'ın kederinin manzaraya yansıması olarak okunur; romantik manzarada doğa iç dünyanın dilidir.'),
  ('Bir sanat tarihçisi \'Courbet manzarayı bile ağır ve maddesel resmederdi\' diyor. Bu gözlemi en iyi destekleyen özellik hangisidir?', 'Kayaları ve dalgaları palet bıçağıyla kalın, dokulu boya katmanlarıyla kurması', ['Gökyüzünü saydam suluboyayla göstermesi', 'Manzaralarını noktacı yöntemle yapması', 'Manzaraya her zaman melekler eklemesi'], 'Courbet\'nin Jura kayalıkları ve deniz manzaraları, boyanın kendisini taş ve su kadar somut hissettiren bir maddesellik taşır.'),
  ('Bir ressam 1890\'larda kendi deneyimlerini, örneğin kaygıyı ve kıskançlığı, birbirine bağlı bir eser dizisinde yan yana sergilemek istiyor; amacı bir öykü değil, ruhun hallerini göstermek. Bu yaklaşım en çok hangi sanatçının projesine benzer?', 'Edvard Munch', ['Gustave Caillebotte', 'Jean-Léon Gérôme', 'Rosa Bonheur'], 'Munch\'un \'Yaşam Frizi\', aşk, kaygı ve ölüm gibi ruh hallerini birbirine bağlanan tablolarla bir bütün olarak sunmayı amaçlamıştır.'),
  ('Bir öğrenci \'Van Gogh hayattayken hiç tanınmadı\' diyor. Hangisi bu yargıyı biraz düzelten bir bilgidir?', 'Ölümünden az önce övgü dolu bir makale çıkması ve bir eserinin satılması', ['Yaşarken akademi üyesi seçilmesi', 'Paris Salonu\'nda altın madalya alıp devletten büyük bir sipariş kazanması', 'Bütün eserlerinin yaşarken satılması'], 'Van Gogh yaşamının sonuna doğru eleştirmen ve sanatçı çevrelerinde ilgi görmeye başlamıştı; ancak geniş ün ölümünden sonra gelmiştir.'),
  ('Bir öğrenci Cézanne\'ın \'Kâğıt Oyuncuları\' dizisinde oyuncuların hiç konuşmadan, kartlarına odaklanmış oturmasını inceliyor. Bu sessizliğin Cézanne\'ın amaçlarıyla ilişkisi nedir?', 'Anlatı ve olay yerine kalıcı biçim ve denge arayışını öne çıkarması', ['Kumarın ahlaki tehlikesini anlatmak istemesi', 'Bir tiyatro oyununu belgelemesi', 'Oyunun kurallarını öğretmek amacı'], 'Cézanne türsel bir sahneyi neredeyse natürmort gibi, durgun ve anıtsal kütlelerle kurarak anlatıdan çok yapıya odaklanır.'),
  ('Bir öğretmen öğrencilerine Degas, Monet ve Renoir\'ın \'modern yaşamı\' farklı biçimlerde ele aldığını söylüyor. Hangisi doğru bir eşleştirmedir?', 'Degas iç mekânlar, Monet açık havada ışık, Renoir neşeli eğlenceler', ['Degas deniz savaşları, Monet saray portreleri, Renoir tarih resimleri', 'Degas: dinsel sahneler; Monet: heykel; Renoir: karikatür', 'Üçü de yalnız antik mitolojiyi resmetmiştir'], 'Degas iç mekân ve hareketli bedenlere, Monet manzarada ışığa, Renoir ise dans ve piknik gibi toplumsal keyiflere yönelmiştir.'),
  ('Bir öğrenci \'Romantikler doğayı sevdi, izlenimciler de doğayı sevdi; o halde aynılar\' diyor. İki akımın doğaya yaklaşımındaki farkı en iyi hangisi açıklar?', 'Romantikler doğada duygu ve anlam, izlenimciler ışık ve renk aramıştır', ['Romantikler doğayı hiç resmetmemiştir', 'İzlenimciler doğayı yalnız gece resmetmiştir', 'İki akım da doğayı yalnız atölyede hayal ederek resmetmiştir'], 'Friedrich ya da Turner için doğa yücelik, inanç ve duygu taşırken Monet ve Sisley için görme deneyiminin konusudur.'),
  ('Bir öğrenci Delacroix\'nın \'Halka Yol Gösteren Özgürlük\' tablosundaki silindir şapkalı burjuva ile işçi kılıklı figürlerin yan yana bulunmasını yorumluyor. En uygun yorum hangisidir?', 'Devrimin farklı toplumsal sınıfları ortak bir amaçta birleştirdiğini göstermesi', ['Burjuvaların işçilere saldırdığını göstermesi', 'Sahnenin bir kostüm balosu olduğunu göstermesi', 'Figürlerin rastgele seçildiğini göstermesi'], '1830 Temmuz Devrimi\'ni anlatan tablo, burjuva, işçi ve sokak çocuğunu aynı barikatta göstererek ulusal birliği vurgular.'),
  ('Bir öğrenci Millet\'nin \'Başak Toplayanlar\' tablosunda öndeki üç kadının ağır ağır eğilmesine karşın arka planda hasat yığınlarının ve atlı bir kâhyanın bulunmasını yorumluyor. Bu karşıtlık neyi vurgular?', 'Bolluk ile yoksulların yalnız artakalana erişmesi arasındaki eşitsizliği', ['Kadınların çiftliğin sahibi olduğunu', 'Hasadın kuraklık yüzünden başarısız geçtiğini ve tarlaların boş kaldığını', 'Sahnenin bir bayram şenliği olduğunu'], 'Başak toplamak en yoksulların hakkıydı; arka plandaki zengin hasat ile öndeki yorgun kadınlar sınıf farkını sessizce gözler önüne serer.'),
  ('Bir öğrenci \'Akademik ressamlar teknik açıdan zayıftı, bu yüzden unutuldular\' diyor. Bu yargıyı en iyi düzelten açıklama hangisidir?', 'Teknikleri ustaydı; modernist anlatı yeniliği öne çıkardığı için geri planda kaldılar', ['Akademik ressamlar fırça kullanmayı bilmiyordu', 'Akademik ressamların eserleri müzelere alınmamış, büyük kısmı yok edilmiştir', 'Akademik ressamlar yalnız fotoğraf çekiyordu'], 'Bouguereau ve Cabanel gibi ressamlar kusursuz bir zanaat sergilemiştir; 20. yüzyılın avangart odaklı anlatısı onları geri plana itmiş, son yıllarda yeniden değerlendirilmişlerdir.'),
  ('Bir sergi tasarımcısı 19. yüzyıl Fransız resmini anlatan bir sergide \'çizginin savunucuları\' ve \'rengin savunucuları\' olarak iki salon kurmak istiyor. Hangi ikili bu ayrıma en uygun düşer?', 'Ingres ve Delacroix', ['Monet ve Renoir', 'Seurat ve Signac', 'Millet ve Courbet'], '19. yüzyıl başının \'çizgi-renk\' tartışması en açık biçimde Ingres ile Delacroix\'nın karşıtlığında simgelenir.'),
  ('Bir öğrenci Toulouse-Lautrec\'in eserlerini Degas\'nınkilerle karşılaştırıyor. Hangisi iki sanatçı arasındaki benzerliği en iyi açıklar?', 'Eğlence dünyasını kesik kadraj ve keskin gözlemle resmetmeleri', ['İkisinin de yalnız manzara yapması', 'İkisinin de Tahiti\'de yaşaması', 'İkisinin de Seurat\'dan öğrendiği noktacı tekniği bütün eserlerinde kullanması'], 'Lautrec, Degas\'ya büyük hayranlık duymuş; kafe, kabare ve tiyatro sahnelerinde onun kesik kompozisyonlarını ve psikolojik gözlemini kendi diliyle sürdürmüştür.'),
  ('Bir öğrenci Pissarro\'nun bir dönem noktacılığı denedikten sonra bırakmasını değerlendiriyor. Bu karar hakkında en makul çıkarım hangisidir?', 'Yavaş ve sistemli yöntem kendiliğinden gözlemini kısıtlamıştır', ['Noktacılığın yasaklanması üzerine bırakmıştır', 'Boya bulamadığı için bırakmıştır', 'Seurat\'nın onu gruptan atması ve eserlerini sergilerden çıkarması üzerine bırakmıştır'], 'Pissarro mektuplarında yöntemin duyguyu ve canlılığı boğduğunu, çok yavaş olduğunu yazmış ve daha özgür bir izlenimci dokunuşa dönmüştür.'),
  ('Bir sanat öğretmeni \'Monet\'nin bir dizisi, aynı motifin ışıkla nasıl değiştiğini gösterir; Cézanne\'ın dizisi ise aynı motifin resimde nasıl yeniden kurulduğunu\' diyor. Bu karşılaştırmada Cézanne\'ın dizisi hangisidir?', 'Sainte-Victoire Dağı tabloları', ['Rouen Katedrali tabloları', 'Nilüfer panoları', 'Saint-Lazare Garı tabloları'], 'Monet katedral ve saman yığınlarında ışığın zamanını izlerken Cézanne Sainte-Victoire\'da resmin yapısını ve mekân sorununu araştırmıştır.'),
  ('Bir öğrenci 19. yüzyılda manzara resminin tür hiyerarşisindeki yerinin yükselmesini açıklamak istiyor. Hangisi bu yükselişin en önemli nedenlerinden biridir?', 'Constable\'dan izlenimcilere uzanan ressamların manzarayı yüceltmesi', ['Akademinin manzarayı yasaklaması', 'Manzaranın yalnızca fotoğrafla yapılır hale gelmesi ve ressamların ondan çekilmesi', 'Tarih resminin daha ucuza satılması'], 'Yüzyıl boyunca doğrudan doğa gözlemine dayanan manzaralar sergilerde ve piyasada öne çıkmış, tarih resminin üstünlüğünü sarsmıştır.'),
  ('Bir öğrenci Rosa Bonheur\'ün döneminde çok ünlü olmasını, kadın sanatçıların genel olarak karşılaştığı engellerle birlikte değerlendiriyor. En dengeli yorum hangisidir?', 'Bonheur istisnai bir başarıdır; kadınlara yönelik yapısal engelleri kaldırmamıştır', ['Bonheur\'ün başarısı, o dönemde kadın sanatçılar için hiçbir engel olmadığını kanıtlar', 'Bonheur hiç eser satamamıştır', 'Bonheur yalnızca erkek adıyla sergi açabilmiştir'], 'Bonheur uluslararası ün ve Legion d\'honneur kazanmış; ama kadınların akademiden ve çıplak model eğitiminden dışlanması gibi sorunlar sürmüştür.'),
  ('Bir öğrenci \'Neden Seurat\'nın tablolarındaki figürler donmuş gibi görünürken Degas\'nınkiler hareket halinde yakalanmış gibidir?\' diye soruyor. En uygun açıklama hangisidir?', 'Seurat kalıcı bir düzen, Degas anlık ve kesik bir hareket aramıştır', ['Seurat yalnız heykel yapmıştır', 'Degas hiç figür resmetmemiştir', 'İkisinin de aynı yöntemle, aynı atölyede ve aynı modellerle çalışmış olması'], 'Seurat\'nın hesaplı, sabit düzeni ile Degas\'nın fotoğrafik anı yakalama isteği iki farklı modern yaklaşımı temsil eder.'),
];
